/* Aztec Conquest — engine.
 *
 * A feature-engine time model (ARCHITECTURE-PATTERNS §1): one scalar t drives
 * everything; every render is a pure function of state; every entity carries a
 * window; cards rewrite themselves for the current time.
 *
 * The canonical frame (SCOPE §5): t is a JULIAN fractional year. All Nahua
 * calendar equivalents shown anywhere are correlations and say so.
 *
 * The default view is the argument (SCOPE §1): the map draws ALLEGIANCE per
 * altepetl per day, from the state series generated by the research models.
 * If a first glance shows two colours, the model has already lied.
 *
 * Data files are GENERATED by Research/modeling/emit.py — do not hand-edit.
 */
'use strict';

const D = window.DATA;
const $ = s => document.querySelector(s);
const svg = $('#map');
const SVGNS = 'http://www.w3.org/2000/svg';

// ------------------------------------------------------------------ state --
const T0 = D.meta.t0, T1 = D.meta.t1;
const [CAMP0, CAMP1] = D.meta.campaign;
const SPEEDS = D.meta.speeds;

// The camera is continuous (round 3): centre + lon-span, animated between the
// named presets, wheel-zoomable about the cursor, drag-pannable. `view` tracks
// the nearest preset purely for the buttons and the hash.
function camOf(v) {
  return {cx: (v.lon0 + v.lon1) / 2, cy: (v.lat0 + v.lat1) / 2,
          span: v.lon1 - v.lon0};
}

const state = {
  t: 1519.0,                         // open on the eve of the war
  playing: false,
  speed: 2,
  view: 'meso',
  cam: null,                          // set at boot from the view preset
  layers: {},
  selection: null,
};

const LAYERS = D.meta.layers;
LAYERS.forEach(l => { state.layers[l.id] = l.on !== false; });

// --------------------------------------------------- the Julian calendar --
// Mirrors Research/modeling/calendar.py (the conversions' home); this is the
// display half only. One day = 1/365-or-366 of the Julian year.
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
             'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function yearDays(y) { return y % 4 === 0 ? 366 : 365; }

function julianOfT(t) {
  let y = Math.floor(t);
  let doy = Math.round((t - y) * yearDays(y));
  doy = Math.max(0, Math.min(yearDays(y) - 1, doy));
  const L = [31, y % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let m = 0;
  while (doy >= L[m]) { doy -= L[m]; m++; }
  return [y, m + 1, doy + 1];
}

const inCampaign = t => t >= CAMP0 && t <= CAMP1;

function fmtT(t) {
  const [y, m, d] = julianOfT(t);
  return inCampaign(t) ? `${d} ${MON[m - 1]} ${y}` : String(y);
}

/* Keyboard/button step: one day inside the campaign, one month outside. */
function stepOf(t) { return inCampaign(t) ? 1 / 365.25 : 1 / 12; }

/* Season of the central-Mexican year: wet roughly May-October. Drives the
 * basemap crossfade, the cloud density and the lake pulse — a modelled
 * rendering of the climate's annual breath, and labelled as such in About. */
function wetness(t) {
  const [, m, d] = julianOfT(t);
  if (m >= 6 && m <= 9) return 1;
  if (m === 5) return d / 31;
  if (m === 10) return 1 - d / 31;
  return 0;
}

// ----------------------------------------------- non-linear time scale --
/* The scrubber is PIECEWISE (SCOPE §2): the campaign carries 56% of the track.
 * xOf and tOf are exact inverses; the breakpoints are drawn on the track and
 * labelled, so nobody mistakes the scale for linear. */
const TS = D.meta.timescale;

function xOf(t) {
  let x = 0;
  for (const s of TS) {
    if (t >= s.to) { x += s.w; continue; }
    if (t <= s.from) return x;
    return x + s.w * (t - s.from) / (s.to - s.from);
  }
  return 1;
}

function tOf(x) {
  let acc = 0;
  for (const s of TS) {
    if (x >= acc + s.w) { acc += s.w; continue; }
    if (x <= acc) return s.from;
    return s.from + (s.to - s.from) * (x - acc) / s.w;
  }
  return T1;
}

// ------------------------------------------------------------- projection --
/* Plate carrée about the camera, with the lon scale corrected by cos(mid-lat)
 * so Basin shapes are not stretched. The terrain basemaps in web/img/ are
 * rendered by build/terrain.py in EXACTLY this mapping over the preset
 * extents — the projection and the basemaps are a matched pair; change one,
 * change both. */
let PROJ = null;

function computeProj() {
  const c = state.cam;
  const r = svg.getBoundingClientRect();
  const W = r.width, H = r.height;
  const kx = Math.cos(c.cy * Math.PI / 180);
  const s = (W * 0.94) / (c.span * kx);            // px per degree (x, km-true)
  PROJ = {kx, s, W, H,
          x0: W / 2 - c.cx * kx * s,
          y0: H / 2 - 55 + c.cy * s};              // slight upward bias for the timeline
}

function project(lon, lat) {
  return [PROJ.x0 + lon * PROJ.kx * PROJ.s, PROJ.y0 - lat * PROJ.s];
}

function unproject(x, y) {
  return [(x - PROJ.x0) / (PROJ.kx * PROJ.s), (PROJ.y0 - y) / PROJ.s];
}

// the lon/lat window currently on screen, [lo0, la0, lo1, la1] — the bound that
// keeps per-plot and per-patch loops at constant cost no matter how far in the
// camera goes
function viewWindow(pad = 0.02) {
  const r = svg.getBoundingClientRect();
  const [lo0, la1] = unproject(0, 0);
  const [lo1, la0] = unproject(r.width, r.height);
  const dx = (lo1 - lo0) * pad, dy = (la1 - la0) * pad;
  return [lo0 - dx, la0 - dy, lo1 + dx, la1 + dy];
}

function onScreen(x, y, m = 40) {
  const r = svg.getBoundingClientRect();
  return x > -m && y > -m && x < r.width + m && y < r.height + m;
}

// -------------------------------------------------------------- time model --
function activeAt(e, t) {
  if (e.from != null && t < e.from) return false;
  if (e.to != null && t > e.to) return false;
  return true;
}

function fadeIn(t, from, span) {
  if (from == null || from <= T0) return 1;
  return Math.max(0, Math.min(1, (t - from) / (span || 0.05)));
}

function lastLE(S, t) {
  let v = null;
  for (const row of S || []) { if (row[0] <= t) v = row[1]; else break; }
  return v;
}

function eraAt(t) {
  return D.eras.find(e => t >= e.from && t < e.to) || D.eras[D.eras.length - 1];
}

/* THE canonical allegiance reader — every consumer goes through this
 * (ARCHITECTURE-PATTERNS §4: one function returns the state; nothing reads a
 * second copy). */
function allegianceAt(e, t) { return lastLE(e.allegiance, t); }

/* Deterministic pseudo-random for the figure-scale impressions: a pure
 * function of the seed, so every scrub replays the same world. NEVER use
 * Math.random in a render path. */
function rnd(s) {
  const x = Math.sin(s * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

/* Smooth value noise on the world grid — for things that come in patches
 * (woodland stands, worked fields) rather than per-point coin flips. */
function smoothNoise(lon, lat, cell) {
  const gx = Math.floor(lon / cell), gy = Math.floor(lat / cell);
  const fx = lon / cell - gx, fy = lat / cell - gy;
  const v = (a, b) => rnd(a * 3701 + b * 8117);
  const sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
  const top = v(gx, gy) * (1 - sx) + v(gx + 1, gy) * sx;
  const bot = v(gx, gy + 1) * (1 - sx) + v(gx + 1, gy + 1) * sx;
  return top * (1 - sy) + bot * sy;
}

function pointInPoly(lat, lon, pts) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const [xi, yi] = pts[i], [xj, yj] = pts[j];
    if ((yi > lat) !== (yj > lat) &&
        lon < (xj - xi) * (lat - yi) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

const ALTEPETL = D.entities.filter(e => e.layer === 'altepetl');
const WORKS = D.entities.filter(e => e.layer === 'works');
const BY_ID = {};
D.entities.forEach(e => { BY_ID[e.id] = e; });
const TENOCH = BY_ID['tenochtitlan'];
const TRACK_EVENTS = D.eventsFull.filter(e => e.track);

// ----------------------------------------------------------------- render --
// ---------------------------------------------------------- world canvas --
/* The dense raster world — terrain, lakes and the city's own fabric — lives on
 * a canvas under the SVG. Google-Earth-grade urban fabric is thousands of
 * marks per frame, and SVG nodes are not free (ARCHITECTURE-PATTERNS §1:
 * canvas above a few thousand). Everything interactive or labelled stays in
 * the SVG above. Both use project(), so they are a matched pair. */
const cvs = $('#world');
const ctx = cvs.getContext('2d');
const TERRAIN_IMG = {};

/* Each terrain image is sampled ONCE at load into a small grid. The ground
 * detail then reads that array instead of calling getImageData on the live
 * canvas every frame — the readback stalled the pipeline at 64 ms/frame. */
const TERRAIN_SAMP = {};

function sampleTerrain(id, img) {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 160;
  const x = c.getContext('2d', {willReadFrequently: true});
  x.drawImage(img, 0, 0, c.width, c.height);
  let data;
  try { data = x.getImageData(0, 0, c.width, c.height).data; } catch (e) { return; }
  let sum = 0;
  for (let i = 0; i < data.length; i += 4) sum += (data[i] + data[i + 1] + data[i + 2]) / 3;
  TERRAIN_SAMP[id] = {w: c.width, h: c.height, data,
                      mean: sum / (data.length / 4)};
}

/* Images must carry the data version too. The build stamps CSS, JS and data
 * but NOT img/, so a re-rendered basemap reached a returning viewer as the
 * OLD picture — the same silent staleness the deploy rules warn about, and it
 * cost a full diagnosis loop when a fixed ocean still looked broken on screen
 * while the file on disk was already correct. */
// In production this is the build's stamp. In DEV there is no stamp, and a
// constant 'dev' pinned the stale entry forever — a cache-buster that busted
// nothing, which cost another cycle. Dev gets a per-load value instead.
const DV = (window.DATA && DATA.meta && DATA.meta.dataVersion) || ('dev-' + Date.now());
const bust = url => url + (url.indexOf('?') < 0 ? '?dv=' : '&dv=') + DV;

function preloadTerrain() {
  for (const tr of TERRAIN) for (const s of ['dry', 'wet']) {
    const im = new Image();
    im.onload = () => { if (s === 'dry') sampleTerrain(tr.id, im); render(); };
    im.src = bust(`img/terrain-${tr.id}-${s}.jpg`);
    TERRAIN_IMG[tr.id + '-' + s] = im;
  }
}

/* Finest loaded terrain level covering the point → [r,g,b,mean]. */
const SAMP_ORDER = ['city', 'basin', 'corridor', 'meso'];
function sampleGround(lon, lat) {
  for (const id of SAMP_ORDER) {
    const s = TERRAIN_SAMP[id];
    if (!s) continue;
    const v = (D.meta.terrain || D.meta.views)[id];
    if (!v || lon < v.lon0 || lon > v.lon1 || lat < v.lat0 || lat > v.lat1) continue;
    const ix = Math.min(s.w - 1, (lon - v.lon0) / (v.lon1 - v.lon0) * s.w | 0);
    const iy = Math.min(s.h - 1, (v.lat1 - lat) / (v.lat1 - v.lat0) * s.h | 0);
    const o = (iy * s.w + ix) * 4;
    return [s.data[o], s.data[o + 1], s.data[o + 2], s.mean];
  }
  return null;
}

function sizeCanvas() {
  const r = svg.getBoundingClientRect();
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  if (cvs.width !== Math.round(r.width * dpr) ||
      cvs.height !== Math.round(r.height * dpr)) {
    cvs.width = Math.round(r.width * dpr);
    cvs.height = Math.round(r.height * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return r;
}

/* Sun from the NW, matching the terrain hillshade: shadows fall to the SE.
 * One constant, so the raster and the vector world agree about the light. */
const SUN = {dx: 0.55, dy: 0.62};

function cpath(pts, close) {
  ctx.beginPath();
  for (let i = 0; i < pts.length; i++) {
    const [x, y] = project(pts[i][0], pts[i][1]);
    if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y);
  }
  if (close) ctx.closePath();
}

function drawWorld() {
  const r = sizeCanvas();
  ctx.clearRect(0, 0, r.width, r.height);
  ctx.fillStyle = '#161c17';
  ctx.fillRect(0, 0, r.width, r.height);

  for (const f of D.geo.features) {
    if (f.kind !== 'sea') continue;
    cpath(f.points, true);
    ctx.fillStyle = '#0a1422';
    ctx.fill();
  }

  const wet = wetness(state.t);
  ctx.imageSmoothingQuality = 'high';
  for (const tr of TERRAIN) {
    const a = terrainAlpha(tr.id);
    if (a <= 0) continue;
    const v = (D.meta.terrain || D.meta.views)[tr.id];
    const [x0, y0] = project(v.lon0, v.lat1);
    const [x1, y1] = project(v.lon1, v.lat0);
    if (x1 < -40 || y1 < -40 || x0 > r.width + 40 || y0 > r.height + 40) continue;
    const dry = TERRAIN_IMG[tr.id + '-dry'], wl = TERRAIN_IMG[tr.id + '-wet'];
    if (dry && dry.complete && dry.naturalWidth) {
      ctx.globalAlpha = a;
      ctx.drawImage(dry, x0, y0, x1 - x0, y1 - y0);
    }
    if (wet > 0.02 && wl && wl.complete && wl.naturalWidth) {
      ctx.globalAlpha = a * wet;
      ctx.drawImage(wl, x0, y0, x1 - x0, y1 - y0);
    }
    ctx.globalAlpha = 1;
  }

  drawGroundDetail();                              // grain + vegetation on land
  if (state.layers.water) drawLakes(wet);
  if (state.layers.city) {
    drawSettlements();
    drawCityFabric();
  }
}

// ------------------------------------------------------- ground detail --
/* Below the data's own grain (ARCHITECTURE-PATTERNS §7 — procedural detail).
 * MEASURED: the city basemap is already 16.6 m/px against SRTM's ~30 m native
 * grain, while street zoom asks for ~1.1 m/px. No tile pyramid can close that
 * — the elevation does not exist below 30 m. What does exist is the measured
 * surface's own colour, so the detail is GROWN from it: woodland clumps where
 * the render is dark and green, dry scrub where it is pale, terraced field
 * lines on worked ground near the towns, nothing at all on water. Positions
 * are world-anchored and deterministic, so the ground holds still when you
 * pan and replays identically when you scrub. */
const auxC = document.createElement('canvas');
auxC.width = 200; auxC.height = 130;
const auxX = auxC.getContext('2d', {willReadFrequently: true});

/* Grain. Upscaling a 30 m raster to 1 m leaves smooth smear where real ground
 * has texture; one tiled noise fill in overlay mode restores it for the cost
 * of a single draw, world-anchored modulo the tile so it does not swim. */
let noisePat = null;
function ensureNoise() {
  if (noisePat) return;
  const n = document.createElement('canvas');
  n.width = n.height = 64;
  const nx = n.getContext('2d');
  const id = nx.createImageData(64, 64);
  // grey grain carried in the ALPHA channel: a plain source-over fill then
  // costs one draw, where an overlay blend cost tens of milliseconds
  for (let i = 0; i < 64 * 64; i++) {
    const r = rnd(i * 1.7);
    id.data[i * 4] = id.data[i * 4 + 1] = id.data[i * 4 + 2] = r > 0.5 ? 236 : 24;
    id.data[i * 4 + 3] = Math.abs(r - 0.5) * 150;
  }
  nx.putImageData(id, 0, 0);
  noisePat = ctx.createPattern(n, 'repeat');
}

function drawGrain(strength) {
  ensureNoise();
  if (!noisePat) return;
  const [ax, ay] = project(-99.0, 19.4);
  ctx.save();
  ctx.globalAlpha = strength;
  ctx.translate(((ax % 64) + 64) % 64 - 64, ((ay % 64) + 64) % 64 - 64);
  ctx.fillStyle = noisePat;
  ctx.fillRect(0, 0, PROJ.W + 128, PROJ.H + 128);
  ctx.restore();
}

function drawGroundDetail() {
  const span = state.cam.span;
  if (span > 0.30 || !PROJ.W) return;
  // grain first, so vegetation and fabric sit crisply on top of it
  drawGrain(Math.min(0.34, 0.08 + (0.30 - span) * 1.0));
  const cols = 92;
  const step = span / cols;
  const lon0 = state.cam.cx - span / 2, lon1 = state.cam.cx + span / 2;
  const latH = PROJ.H / PROJ.s;
  const lat0 = state.cam.cy - latH / 2, lat1 = state.cam.cy + latH / 2;
  const fp = CITY_BY_ID_FP();
  const sz = Math.max(0.9, step * PROJ.s * 0.32);
  const q = v => Math.floor(v / step) * step;
  // woodland is what is DARKER than its surroundings, not what is green (the
  // wet-season palette is green everywhere, which blanketed the first attempt)
  for (let lat = q(lat0); lat < lat1 + step; lat += step) {
    for (let lon = q(lon0); lon < lon1 + step; lon += step) {
      const s = Math.round(lon * 1e6) * 7919 + Math.round(lat * 1e6);
      const smp = sampleGround(lon, lat);
      if (!smp) continue;
      const [R, G, B, meanLum] = smp;
      if (B > G + 6) {
        // WATER. The sea floor's relief is real ETOPO, but its grid runs out
        // before the screen does — the same ceiling as the land. So sub-grid
        // fabric is GROWN from the measured relief: lineation only where the
        // floor is genuinely darker than its own neighbourhood (a slope, a
        // scarp, a trench wall), aligned to a slowly-turning field. Flat
        // abyss stays flat, which is the truth about it.
        if (span > 0.9) continue;
        let ws = 0, wn = 0;
        for (const [dl, dt] of [[0.006, 0], [-0.006, 0], [0, 0.006], [0, -0.006]]) {
          const nb = sampleGround(lon + dl, lat + dt);
          if (nb) { ws += (nb[0] + nb[1] + nb[2]) / 3; wn++; }
        }
        const wl = (R + G + B) / 3;
        const wLocal = wn ? (ws + wl) / (wn + 1) : wl;
        const relief = Math.max(0, (wLocal - wl) / 9);
        if (relief < 0.12 || rnd(s + 11) > Math.min(0.5, relief * 0.5)) continue;
        const [wx, wy] = project(lon, lat);
        if (wx < 0 || wy < 0 || wx > PROJ.W || wy > PROJ.H) continue;
        const wa = (smoothNoise(lon, lat, 0.05) - 0.5) * 2.0 + 0.4;
        const len = sz * (2.2 + rnd(s + 12) * 2.4);
        ctx.strokeStyle = `rgba(${Math.max(6, R * 0.62) | 0},${Math.max(16, G * 0.66) | 0},` +
                          `${Math.max(34, B * 0.72) | 0},` +
                          `${Math.min(0.34, relief * 0.30).toFixed(3)})`;
        ctx.lineWidth = Math.max(0.5, sz * 0.42);
        ctx.beginPath();
        ctx.moveTo(wx - Math.cos(wa) * len, wy - Math.sin(wa) * len);
        ctx.lineTo(wx + Math.cos(wa) * len, wy + Math.sin(wa) * len);
        ctx.stroke();
        continue;
      }
      if (fp && pointInPoly(lat, lon, fp)) continue;   // the island has its fabric
      const [x, y] = project(lon + (rnd(s) - 0.5) * step * 0.95,
                             lat + (rnd(s + 1) - 0.5) * step * 0.95);
      if (x < 0 || y < 0 || x > PROJ.W || y > PROJ.H) continue;
      const lum = (R + G + B) / 3;
      // LOCAL contrast, not the whole image's: a dark valley must not read as
      // wall-to-wall forest just because it is darker than the map average
      let ls = 0, ln = 0;
      for (const [dl, dt] of [[0.0045, 0], [-0.0045, 0], [0, 0.0045], [0, -0.0045]]) {
        const nb = sampleGround(lon + dl, lat + dt);
        if (nb) { ls += (nb[0] + nb[1] + nb[2]) / 3; ln++; }
      }
      const local = ln ? (ls + lum) / (ln + 1) : meanLum;
      const dark = Math.max(0, (local - lum) / 15);        // 0 at local mean
      // stands, not a blanket: smooth noise at ~1 km decides where woodland is
      const st = smoothNoise(lon, lat, 0.010);
      const treeP = Math.min(0.85, dark * 1.1) * (st > 0.56 ? 1 : 0.10);
      if (rnd(s + 2) < treeP) {                    // woodland
        ctx.fillStyle = `rgba(${Math.max(26, R * 0.50) | 0},${Math.max(44, G * 0.62) | 0},` +
                        `${Math.max(24, B * 0.44) | 0},.7)`;
        ctx.beginPath();
        ctx.arc(x, y, sz * (0.6 + rnd(s + 3) * 0.7), 0, 7);
        ctx.fill();
      } else if (rnd(s + 4) < 0.10) {              // dry scrub and stone
        ctx.fillStyle = `rgba(${(R * 0.84) | 0},${(G * 0.82) | 0},${(B * 0.72) | 0},.32)`;
        ctx.fillRect(x, y, sz * 0.7, sz * 0.5);
      }
      // terraced plots on the worked ground around the towns
      if (span < 0.06 && smoothNoise(lon, lat, 0.010) < 0.42 && rnd(s + 6) < 0.16) {
        ctx.strokeStyle = `rgba(${(R * 0.72) | 0},${(G * 0.72) | 0},${(B * 0.6) | 0},.4)`;
        ctx.lineWidth = Math.max(0.4, sz * 0.18);
        const w = sz * (3 + rnd(s + 7) * 5);
        ctx.beginPath(); ctx.moveTo(x - w / 2, y); ctx.lineTo(x + w / 2, y); ctx.stroke();
      }
    }
  }
}

// --------------------------------------------------- settlements at large --
/* Every altepetl gets its own fabric, not just the capital: a plaza with its
 * temple platform, streets out of it, house compounds thinning with distance,
 * orchards at the fringe, and a church once the polity passes into New Spain.
 * Size follows the polity's standing; layout follows the Mesoamerican town
 * form (a civic-ceremonial core with dispersed residential wards). An
 * impression, deterministic per settlement id. */
function hashStr(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return Math.abs(h) % 100000;
}

const SETTLE_R = {'Triple Alliance seat': 0.0075, 'Rival empire': 0.0068,
                  'Independent polity': 0.0055, 'Tributary altepetl': 0.0036,
                  'Spanish foundation': 0.0026};

function drawSettlements() {
  const p = PROJ.s;
  const phase = cityPhaseAt(state.t);
  if (0.0036 * p < 9) return;                      // nothing legible yet
  const r = {width: cvs.width, height: cvs.height};
  for (const e of ALTEPETL) {
    if (e.id === 'tenochtitlan' || e.id === 'tlatelolco') continue;
    if (!activeAt(e, state.t)) continue;
    const st = allegianceAt(e, state.t);
    if (!st) continue;
    const R = SETTLE_R[e.kind] || 0.0034;
    const Rpx = R * p;
    if (Rpx < 7) continue;
    const [cx, cy] = project(e.lon, e.lat);
    if (cx < -Rpx * 2 || cy < -Rpx * 2 || cx > r.width + Rpx * 2 ||
        cy > r.height + Rpx * 2) continue;
    drawSettlement(e, cx, cy, R, Rpx, st, phase);
  }
}

function drawSettlement(e, cx, cy, R, Rpx, st, phase) {
  const seed = hashStr(e.id);
  const p = PROJ.s;
  const lod = Rpx > 60 ? 2 : Rpx > 22 ? 1 : 0;
  const colonial = st === 'new-spain' || st === 'colonial-ally';
  const sacked = st === 'occupied' && state.t < 1522.2;

  // the cleared ground the town sits on
  ctx.beginPath();
  ctx.ellipse(cx, cy, Rpx, Rpx * 0.86, 0, 0, 7);
  ctx.fillStyle = 'rgba(178,166,140,.42)';
  ctx.fill();

  // streets out of the plaza, on the cardinal-ish axes of the town
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(214,203,178,.5)';
  ctx.lineWidth = Math.max(0.7, Rpx * 0.035);
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2 + (rnd(seed + i) - 0.5) * 0.5;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * Rpx * 1.05, cy + Math.sin(a) * Rpx * 0.92);
    ctx.stroke();
  }

  // THE TOWN'S PLAN. Mesoamerican settlements are not one shape: Tlaxcallan
  // was four separate cabeceras on their own hills; the lakeshore towns ran
  // long against the water; the road towns clustered on their plaza. The plan
  // is chosen per settlement so no two read as the same city.
  const planV = rnd(seed + 41);
  const plan = e.kind === 'Independent polity' && planV < 0.6 ? 'dispersed'
             : planV < 0.30 ? 'dispersed' : planV < 0.66 ? 'compact' : 'linear';
  const axis = (rnd(seed + 43) - 0.5) * 2.2;        // the long axis, for linear towns
  const wards = [];
  if (plan === 'dispersed') {
    const nW = 3 + Math.floor(rnd(seed + 45) * 2);
    for (let i = 0; i < nW; i++) {
      const a = i / nW * Math.PI * 2 + rnd(seed + 50 + i);
      wards.push([cx + Math.cos(a) * Rpx * 0.55, cy + Math.sin(a) * Rpx * 0.48]);
    }
  }
  // the house compounds: dense at the core, dispersed at the edge
  const LOTN = lod >= 2 ? 21 : lod >= 1 ? 12 : 7;
  const cell = (Rpx * 1.9) / LOTN;
  const hg = Math.max(0.5, cell * 0.16);
  for (let iy = 0; iy < LOTN; iy++) {
    for (let ix = 0; ix < LOTN; ix++) {
      const s2 = seed + iy * 131 + ix * 17;
      const jx = (rnd(s2) - 0.5) * cell * 0.6, jy = (rnd(s2 + 1) - 0.5) * cell * 0.6;
      const x = cx - Rpx * 0.95 + ix * cell + jx;
      const y = cy - Rpx * 0.82 + iy * cell * 0.9 + jy;
      let d;
      if (plan === 'dispersed') {
        d = 9;
        for (const [wx, wy] of wards)
          d = Math.min(d, Math.hypot(x - wx, y - wy) / (Rpx * 0.42));
        if (d > 1.02) continue;
      } else if (plan === 'linear') {
        const dx = x - cx, dy = y - cy;
        const u = dx * Math.cos(axis) + dy * Math.sin(axis);
        const v = -dx * Math.sin(axis) + dy * Math.cos(axis);
        d = Math.hypot(u / (Rpx * 1.15), v / (Rpx * 0.48));
        if (d > 1.02) continue;
      } else {
        d = Math.hypot((x - cx) / Rpx, (y - cy) / (Rpx * 0.86));
        if (d > 1.02) continue;
      }
      if (rnd(s2 + 2) > 1.0 - d * 0.62) continue;   // thins outward
      if (plan !== 'dispersed' && d < 0.20) continue;   // the plaza stays open
      const bw = cell * (0.34 + rnd(s2 + 3) * 0.30);
      const bh = cell * (0.28 + rnd(s2 + 4) * 0.26);
      if (lod >= 1) {
        ctx.fillStyle = 'rgba(28,22,16,.30)';
        ctx.fillRect(x + hg * 0.9, y + hg, bw, bh);
      }
      ctx.fillStyle = sacked && rnd(s2 + 7) > 0.55 ? 'rgba(48,38,30,1)'
        : colonial && rnd(s2 + 7) > 0.6 ? 'rgba(200,146,118,1)'
        : rnd(s2 + 5) > 0.7 ? 'rgba(176,150,106,1)'   // thatch
                            : `rgba(${210 + rnd(s2 + 6) * 22 | 0},${196 + rnd(s2 + 6) * 20 | 0},166,1)`;
      ctx.fillRect(x, y, bw, bh);
      if (lod >= 1) {
        ctx.fillStyle = 'rgba(120,102,78,.38)';
        ctx.fillRect(x, y + bh, bw, hg * 0.7);
      }
      // an orchard tree beside the outer compounds
      if (lod >= 2 && d > 0.5 && rnd(s2 + 8) > 0.55) {
        ctx.fillStyle = 'rgba(64,98,54,.85)';
        ctx.beginPath();
        ctx.arc(x + bw * 1.5, y + bh * 0.6, Math.max(0.8, cell * 0.13), 0, 7);
        ctx.fill();
      }
    }
  }

  // the civic-ceremonial core: plaza, temple platform, and after the conquest
  // a church on or beside it — the pattern repeated across New Spain
  const pw = Rpx * 0.30;
  ctx.fillStyle = 'rgba(226,217,193,.85)';
  ctx.fillRect(cx - pw, cy - pw * 0.8, pw * 2, pw * 1.6);
  if (!colonial) {
    const tw = pw * 0.85, th = pw * 0.75;
    const tx = cx - tw / 2, ty = cy - th * 1.05;
    ctx.fillStyle = 'rgba(20,15,11,.4)';
    ctx.fillRect(tx + tw * 0.16, ty + th * 0.2, tw, th);
    for (let s = 0; s < 3; s++) {
      const k = s / 3;
      ctx.fillStyle = sacked ? `rgb(${76 - s * 8},${64 - s * 7},${52 - s * 6})`
                             : `rgb(${202 + s * 14},${188 + s * 14},${158 + s * 16})`;
      ctx.fillRect(tx + tw * k * 0.17, ty + th * k * 0.17,
                   tw * (1 - k * 0.34), th * (1 - k * 0.34));
    }
    if (lod >= 1 && !sacked) {
      ctx.fillStyle = 'rgba(168,74,56,1)';
      ctx.fillRect(tx + tw * 0.36, ty + th * 0.30, tw * 0.28, th * 0.26);
    }
    // Chōlōllān's Tlachihualtepetl — the greatest pyramid by volume in the
    // Americas, already ancient and grassed over in 1519, and the ground the
    // massacre happened on
    if (e.id === 'cholula' && lod >= 1) {
      const gw = Rpx * 0.62, gh = Rpx * 0.52;
      const gx2 = cx - Rpx * 0.62, gy2 = cy - Rpx * 0.10;
      ctx.fillStyle = 'rgba(20,15,11,.4)';
      ctx.fillRect(gx2 + gw * 0.14, gy2 + gh * 0.16, gw, gh);
      for (let s = 0; s < 4; s++) {
        const k = s / 4;
        ctx.fillStyle = `rgb(${118 + s * 10},${132 + s * 10},${86 + s * 8})`;
        ctx.fillRect(gx2 + gw * k * 0.15, gy2 + gh * k * 0.15,
                     gw * (1 - k * 0.30), gh * (1 - k * 0.30));
      }
      ctx.fillStyle = 'rgb(200,186,156)';            // the temple on its summit
      ctx.fillRect(gx2 + gw * 0.40, gy2 + gh * 0.38, gw * 0.20, gh * 0.20);
    }
  } else {
    const cw = pw * 0.7, ch = pw * 0.5;
    ctx.fillStyle = 'rgba(20,15,11,.35)';
    ctx.fillRect(cx - cw / 2 + cw * 0.2, cy - ch * 1.2 + ch * 0.25, cw, ch);
    ctx.fillStyle = 'rgba(232,224,206,1)';
    ctx.fillRect(cx - cw / 2, cy - ch * 1.2, cw, ch);
    if (lod >= 1) {                                  // the bell tower's shadow
      ctx.fillStyle = 'rgba(214,204,186,1)';
      ctx.fillRect(cx - cw / 2, cy - ch * 1.55, cw * 0.26, ch * 0.4);
    }
  }
}

// ------------------------------------------------------------- the water --
/* Real lakes, not blue polygons. Three things make water read as water:
 *   depth — shallow, pale margins darkening to the middle. Drawn by clipping
 *     to the lake and stroking its own boundary in narrowing passes, so the
 *     shallow band follows the true shoreline shape rather than a centroid;
 *   a coastline that is not a straight line between vertices — the drawn
 *     shore is fractally displaced (≤ ~120 m) off the reconstruction's
 *     polygon. THIS IS A RENDERING, not a new claim: the canonical shoreline
 *     stays the named reconstruction's, which is what the witness audit
 *     measures and what every card cites;
 *   surface — ripple, and a sun sheen from the NW to match the terrain's own
 *     light, so the lake belongs to the same world as the ground.
 * The Basin's rivers run in from the sierra and fan into deltas at the
 * margin — a closed basin's streams had nowhere else to go, which is why the
 * lakes existed and why the flood problem never did go away. */
const COAST_CACHE = {};

function crinkled(id, pts, amp) {
  if (COAST_CACHE[id]) return COAST_CACHE[id];
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    const dx = b[0] - a[0], dy = b[1] - a[1];
    const L = Math.hypot(dx, dy) || 1;
    const nx = -dy / L, ny = dx / L;
    // sinuosity scales with the edge it replaces: a long straight run in the
    // simplified reconstruction is exactly where a real shore wanders most
    const per = Math.max(8, Math.min(40, Math.round(L / 0.0022)));
    const scale = amp * Math.min(1.6, 0.5 + L / 0.05);
    for (let k = 0; k < per; k++) {
      const u = k / per;
      const x = a[0] + dx * u, y = a[1] + dy * u;
      // taper to zero at the vertices, so the reconstruction's own corners hold
      const taper = Math.sin(Math.PI * u);
      const d = (smoothNoise(x, y, 0.016) - 0.5) * 1.0
              + (smoothNoise(x, y, 0.006) - 0.5) * 0.6
              + (smoothNoise(x, y, 0.0022) - 0.5) * 0.32;
      out.push([x + nx * d * scale * taper, y + ny * d * scale * taper]);
    }
  }
  COAST_CACHE[id] = out;
  return out;
}

/* The depth ramp. k: 0 = deep, 1 = the waterline. Deliberately NOT linear —
 * the plateau from the shore out, then a steepening, is what reads as a shelf
 * break; a straight interpolation reads as a gradient and nothing else. */
/* THE LAKES ARE SHALLOW. Texcoco ran a metre to three deep over most of its
 * area — the brigantines drew little and the causeway builders waded. So its
 * ramp must live in the SHALLOW end of the palette: teal throughout, never
 * the navy of an ocean basin. The earlier ramp reached rgb(18,44,88) at the
 * middle, which drew a 3 m lake as abyss — accurate-looking water that was
 * wrong about the water. Depth still reads, because the ramp still runs; it
 * just runs across the range the lake actually occupied. */
const DEPTH_STOPS = [
  [0.00, 44, 104, 132, 1.00],    // the deeper middle — still only metres
  [0.22, 52, 118, 146, 1.00],
  [0.42, 64, 138, 162, 0.99],
  [0.55, 82, 158, 174, 0.97],    // the shoal edge
  [0.68, 108, 180, 184, 0.92],
  [0.82, 138, 200, 194, 0.84],
  [0.93, 168, 216, 202, 0.72],
  [1.00, 196, 228, 210, 0.55],   // the waterline, where the bed shows through
];

function depthColour(k, wet) {
  let a = DEPTH_STOPS[0], b = DEPTH_STOPS[DEPTH_STOPS.length - 1];
  for (let i = 0; i < DEPTH_STOPS.length - 1; i++) {
    if (k >= DEPTH_STOPS[i][0] && k <= DEPTH_STOPS[i + 1][0]) {
      a = DEPTH_STOPS[i]; b = DEPTH_STOPS[i + 1]; break;
    }
  }
  const u = (k - a[0]) / Math.max(1e-6, b[0] - a[0]);
  const c = j => Math.round(a[j] + (b[j] - a[j]) * u);
  const al = (a[4] + (b[4] - a[4]) * u) * (0.93 + 0.07 * wet);
  return `rgba(${c(1)},${c(2)},${c(3)},${al.toFixed(3)})`;
}

function deepColour(wet) { return depthColour(0, wet); }

/* Lake-bed fabric. A shallow saline lake is not a flat colour: it carries
 * shoals and sediment plumes, and its margins are tule beds. Rooted in what
 * the Basin's lakes were — saline and shoal-ridden in Texcoco, spring-fed and
 * weed-green in the southern lakes — and world-anchored so it holds still. */
function drawLakeBed(f, pts) {
  const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
  // Bound the work to what is ON SCREEN, not to the whole lake: iterating the
  // full bbox at every zoom cost 52 ms/frame with most of it off-camera.
  const vSpan = state.cam.span, vLatH = PROJ.H / PROJ.s;
  const lo0 = Math.max(Math.min(...xs), state.cam.cx - vSpan / 2 - 0.01);
  const lo1 = Math.min(Math.max(...xs), state.cam.cx + vSpan / 2 + 0.01);
  const la0 = Math.max(Math.min(...ys), state.cam.cy - vLatH / 2 - 0.01);
  const la1 = Math.min(Math.max(...ys), state.cam.cy + vLatH / 2 + 0.01);
  if (lo1 <= lo0 || la1 <= la0) return;
  const fresh = f.id !== 'lake-texcoco';
  // constant screen density, so the cost does not grow as you zoom out
  const step = Math.max(0.00035, (lo1 - lo0) / 105);
  for (let la = la0; la < la1; la += step) {
    for (let lo = lo0; lo < lo1; lo += step) {
      const n = smoothNoise(lo, la, 0.013) * 0.6 + smoothNoise(lo, la, 0.004) * 0.4;
      if (n < 0.46) continue;
      const [bx, by] = project(lo, la);
      if (bx < -20 || by < -20 || bx > PROJ.W + 20 || by > PROJ.H + 20) continue;
      const s = Math.round(lo * 1e5) * 47 + Math.round(la * 1e5);
      const r = step * PROJ.s * (1.1 + rnd(s) * 0.8);
      // DIFFUSE, and mostly darker. A shallow turbid lake shows sediment and
      // shoal as soft patches you half-see — not the long pale feathers the
      // elongated version drew, which read as brush strokes on water. Soft
      // radial falloff, low alpha, and pale only rarely and faintly.
      const strength = Math.min(0.05, (n - 0.46) * 0.14);
      const pale = n > 0.80;
      const col = pale
        ? (fresh ? '150,190,160' : '186,204,200')
        : (fresh ? '26,62,64' : '20,48,80');
      const a = pale ? strength * 0.5 : strength;
      const g = ctx.createRadialGradient(bx, by, 0, bx, by, r);
      g.addColorStop(0, `rgba(${col},${a.toFixed(3)})`);
      g.addColorStop(0.6, `rgba(${col},${(a * 0.45).toFixed(3)})`);
      g.addColorStop(1, `rgba(${col},0)`);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(bx, by, r * 1.5, r * 0.95,
                  (smoothNoise(lo, la, 0.030) - 0.5) * 2.0, 0, 7);
      ctx.fill();
    }
  }
  // tule beds: the reed margin every account of these lakes mentions
  ctx.strokeStyle = fresh ? 'rgba(74,116,72,.40)' : 'rgba(104,128,96,.32)';
  ctx.lineWidth = Math.max(0.6, 0.00005 * PROJ.s);
  cpath(pts, true);
  ctx.setLineDash([Math.max(2, 0.0004 * PROJ.s), Math.max(2, 0.0006 * PROJ.s)]);
  ctx.lineWidth = Math.max(1.2, 0.00035 * PROJ.s);
  ctx.stroke();
  ctx.setLineDash([]);
}

function inPoly(pt, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1], xj = poly[j][0], yj = poly[j][1];
    if ((yi > pt[1]) !== (yj > pt[1]) &&
        pt[0] < (xj - xi) * (pt[1] - yi) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/* The chinampa districts of the southern lakes — the raised fields that fed the
 * Basin, and the reason the dike of Nezahualcóyotl was built to hold the saline
 * water off them. Drawn at TRUE SCALE: a chinampa is a plot of about 6-10 m by
 * 100 m with a canoe canal beside it, so at Basin zoom one plot is a fraction of
 * a pixel. Rather than draw fat fake stripes, the pitch stays true and the
 * renderer drops to a blended tone once a plot falls under ~1.4 px — which is
 * what the chinampería actually looks like from that height anyway. */
function drawChinampas(wet) {
  if (!D.geo.chinampaZones || state.cam.span > 2.0) return;
  const lakes = D.geo.features.filter(f => f.kind === 'lake');
  const PITCH = 0.000115;                  // ~12 m: plot + its canal
  const PLOT  = 0.00082;                   // ~91 m: a plot's long axis
  const px = PITCH * PROJ.s;

  for (const z of D.geo.chinampaZones) {
    const zp = crinkled('chin-' + z.id, z.points, 0.0016);
    const c = [z.points.reduce((s, p) => s + p[0], 0) / z.points.length,
               z.points.reduce((s, p) => s + p[1], 0) / z.points.length];
    const host = lakes.find(f => inPoly(c, f.points));
    ctx.save();
    // clip to the lake FIRST: a chinampa district is water that has been built
    // up, so it can never spill past the shoreline onto dry ground
    if (host) { cpath(crinkled(host.id, host.points, 0.0032), true); ctx.clip(); }
    cpath(zp, true);
    ctx.clip();

    const xs = zp.map(p => p[0]), ys = zp.map(p => p[1]);
    const a0 = Math.min(...xs), a1 = Math.max(...xs);
    const b0 = Math.min(...ys), b1 = Math.max(...ys);
    const vw = viewWindow();
    const lo0 = Math.max(a0, vw[0]), lo1 = Math.min(a1, vw[2]);
    const la0 = Math.max(b0, vw[1]), la1 = Math.min(b1, vw[3]);

    // A chinampa is BUILT GROUND standing out of the lake — not a tint over the
    // water. So the district is painted as land, opaque, and what gets drawn on
    // top is the water cut INTO it. Getting this backwards is what made the
    // first attempt read as a translucent slab floating on the lake.
    const resolved = px >= 1.4;
    const [gx0, gy0] = project(a0, b1), [gx1, gy1] = project(a1, b0);
    const base = ctx.createLinearGradient(0, gy0, 0, gy1);
    if (resolved) {
      // close in, the plots themselves get drawn, so what the base has to be is
      // the DITCH WATER they stand in. Painting land here and land again on top
      // is what made the first pass read as one flat green field.
      base.addColorStop(0, '#2f5560');
      base.addColorStop(1, '#3b6672');
    } else {
      // far out, a single plot is sub-pixel and the honest base is the blend
      base.addColorStop(0, wet ? '#4e6a44' : '#6b7247');  // far edge, wetter
      base.addColorStop(1, wet ? '#5d7a4b' : '#7c8152');  // shore edge, drier
    }
    ctx.fillStyle = base;
    ctx.fillRect(gx0, gy0, gx1 - gx0, gy1 - gy0);
    // the mottle of crop, fallow and standing water within the district
    // constant SCREEN density, not constant world density: a world-anchored
    // step means the cell count explodes as the camera pulls back, which is
    // exactly the shape of the lake-fabric regression from round 6
    const stp = Math.max(0.00022, 5.0 / PROJ.s);
    if (!resolved) {
      const s = stp * PROJ.s + 1;
      for (let lo = lo0; lo < lo1; lo += stp) {
        for (let la = la0; la < la1; la += stp) {
          const n = smoothNoise(lo, la, 0.0019);
          if (n > 0.42 && n < 0.58) continue;        // most cells: nothing to paint
          const [qx, qy] = project(lo, la);
          ctx.fillStyle = n > 0.58 ? `rgba(58,88,48,${((n - 0.58) * 0.9).toFixed(3)})`
                                   : `rgba(78,116,116,${((0.42 - n) * 0.8).toFixed(3)})`;
          ctx.fillRect(qx, qy, s, s);
        }
      }
    } else {
      // The plots themselves, standing out of the ditch water already painted.
      // BATCHED BY CROP COLOUR: a district at this zoom is several thousand
      // plots, and a per-plot fillStyle string plus a per-plot fill is most of
      // the cost. Three colours means three fills, whatever the plot count.
      const w = Math.max(1, PITCH * 0.62 * PROJ.s);
      const CROP = ['rgba(92,132,74,.94)',      // maize standing
                    'rgba(116,140,80,.94)',     // second crop, thinner
                    'rgba(134,132,94,.94)'];    // fallow mud
      const bins = [[], [], []], willows = [];
      const wt = px > 6;
      for (let lo = Math.floor(lo0 / PITCH) * PITCH; lo < lo1; lo += PITCH) {
        // the block ends stagger — a chinampería is not graph paper
        const jit = (rnd(Math.round(lo * 1e5) * 17) - 0.5) * PLOT * 0.30;
        for (let la = Math.floor(la0 / PLOT) * PLOT; la < la1; la += PLOT) {
          const r = rnd(Math.round(lo * 1e5) * 733 + Math.round(la * 1e5) * 91);
          if (r > 0.94) continue;                       // a plot let go to water
          const [qx, qy] = project(lo, la + jit + PLOT * 0.94);
          const [, qy2] = project(lo, la + jit + PLOT * 0.06);
          const g = smoothNoise(lo, la, 0.0022);        // maize, or fallow mud
          bins[g > 0.55 ? 0 : g > 0.42 ? 1 : 2].push(qx, qy, qy2 - qy);
          // the willow (ahuejote) rows whose roots pinned the plots' edges
          if (wt && r > 0.72) {
            const n = Math.max(2, Math.round((qy2 - qy) / (px * 2.2)));
            for (let k = 0; k < n; k++)
              willows.push(qx + w * 0.80, qy + (qy2 - qy) * (k + 0.5) / n);
          }
        }
      }
      for (let b = 0; b < 3; b++) {
        if (!bins[b].length) continue;
        ctx.fillStyle = CROP[b];
        ctx.beginPath();
        for (let i = 0; i < bins[b].length; i += 3)
          ctx.rect(bins[b][i], bins[b][i + 1], w, bins[b][i + 2]);
        ctx.fill();
      }
      if (willows.length) {
        const ws = Math.max(1, px * 0.34);
        ctx.fillStyle = 'rgba(52,80,46,.8)';
        ctx.beginPath();
        for (let i = 0; i < willows.length; i += 2)
          ctx.rect(willows[i], willows[i + 1], ws, ws);
        ctx.fill();
      }
    }

    // the navigation canals — 10-20 m wide and a few hundred metres apart, so
    // unlike the plot ditches these ARE resolvable from height, and they are
    // what gives the chinampería its visible grain at every zoom. Drawn LAST:
    // a canal is water cut through the fields, so it has to survive the plots.
    const CANAL = 0.0042;                       // ~460 m between main canals
    // ...but only while they are far enough apart on screen to read AS canals.
    // Once the spacing tightens past ~16 px a true-scale lattice stops looking
    // like waterways and starts looking like graph paper ruled over the lake,
    // so it fades out and the district's texture carries it instead.
    const cpx = CANAL * PROJ.s;
    const ca = Math.min(1, Math.max(0, (cpx - 7) / 12));
    if (ca <= 0.01) { ctx.restore(); continue; }
    ctx.strokeStyle = resolved ? `rgba(44,84,96,${(0.92 * ca).toFixed(3)})`
                               : `rgba(60,100,112,${(0.85 * ca).toFixed(3)})`;
    ctx.lineWidth = Math.max(0.7, 0.00016 * PROJ.s);
    ctx.beginPath();
    for (let lo = Math.floor(lo0 / CANAL) * CANAL; lo < lo1; lo += CANAL) {
      const w1 = (smoothNoise(lo, b0, 0.004) - 0.5) * 0.0008;
      const [ax, ay] = project(lo + w1, b0 - 0.002);
      const [bx2, by2] = project(lo - w1, b1 + 0.002);
      ctx.moveTo(ax, ay); ctx.lineTo(bx2, by2);
    }
    for (let la = Math.floor(la0 / CANAL) * CANAL; la < la1; la += CANAL) {
      const [ax, ay] = project(a0 - 0.002, la);
      const [bx2, by2] = project(a1 + 0.002, la);
      ctx.moveTo(ax, ay); ctx.lineTo(bx2, by2);
    }
    ctx.stroke();
    ctx.restore();
  }
}

function drawLakes(wet) {
  const zoomed = state.cam.span < 3.0;
  for (const f of D.geo.features) {
    if (f.kind !== 'lake') continue;
    const pts = zoomed ? crinkled(f.id, f.points, 0.0032) : f.points;
    ctx.save();
    cpath(pts, true);
    ctx.clip();
    // OPAQUE water with a hypsometric depth ramp. The reference's ocean works
    // because deep water is opaque and dark while the shelf is pale and you
    // can see structure in it — a translucent wash over the hillshade reads as
    // cellophane, not water. So: fill deep and solid, then lay the shallows
    // back in from the true shoreline, with a SHELF BREAK where the ramp
    // steepens (in Texcoco's case the drop off the shoal into the deeper
    // middle, a matter of a couple of metres but the sharpest gradient there).
    ctx.fillStyle = deepColour(wet);
    ctx.fill();
    // a shallow lake is nearly all shelf: the pale margin reaches far in
    const shelf = Math.max(6, 0.030 * PROJ.s);
    const N = 26;
    for (let i = 0; i < N; i++) {
      const k = i / N;                             // 0 = deepest pass, 1 = shore
      cpath(pts, true);
      ctx.lineWidth = shelf * Math.pow(1 - k, 1.35) * 2;
      ctx.strokeStyle = depthColour(k, wet);
      ctx.stroke();
    }
    // the bed itself, seen through the shallows: salt shoal, sediment and the
    // tule beds of a lake margin — the equivalent of the reference's sea-floor
    // fabric, at a lake's scale
    if (zoomed) drawLakeBed(f, pts);
    if (zoomed) {
      // ripple, world-anchored so it does not swim
      ctx.strokeStyle = 'rgba(226,240,250,.035)';
      ctx.lineWidth = Math.max(0.5, 0.00004 * PROJ.s);
      const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
      const lo0 = Math.min(...xs), lo1 = Math.max(...xs);
      const la0 = Math.min(...ys), la1 = Math.max(...ys);
      const stp = 0.00075;
      ctx.beginPath();
      for (let la = la0; la < la1; la += stp) {
        for (let lo = lo0; lo < lo1; lo += stp * 3) {
          const s = Math.round(lo * 1e5) * 61 + Math.round(la * 1e5);
          if (rnd(s) > 0.45) continue;
          const [wx, wy] = project(lo, la);
          ctx.moveTo(wx, wy);
          ctx.lineTo(wx + Math.max(1.4, stp * PROJ.s * 1.6), wy);
        }
      }
      ctx.stroke();
      // the sun's sheen, from the NW, matching the hillshade's own light
      const [gx0, gy0] = project(lo0, la1);
      const [gx1, gy1] = project(lo1, la0);
      const gr = ctx.createLinearGradient(gx0, gy0, gx1, gy1);
      gr.addColorStop(0, 'rgba(255,252,238,.16)');
      gr.addColorStop(0.28, 'rgba(255,250,235,.05)');
      gr.addColorStop(0.6, 'rgba(255,255,255,0)');
      ctx.fillStyle = gr;
      ctx.fillRect(Math.min(gx0, gx1), Math.min(gy0, gy1),
                   Math.abs(gx1 - gx0), Math.abs(gy1 - gy0));
    }
    ctx.restore();
    // the water's edge itself: a pale line of shoal, then the shore
    cpath(pts, true);
    ctx.lineWidth = Math.max(0.7, 0.00005 * PROJ.s);
    ctx.strokeStyle = `rgba(186,212,222,${(0.34 + 0.16 * wet).toFixed(3)})`;
    ctx.stroke();
  }
  drawChinampas(wet);

  // the rivers, widening downstream, with a delta where they meet the lake
  if (state.cam.span < 3.0 && D.geo.rivers) {
    for (const r of D.geo.rivers) {
      const n = r.points.length;
      // a river cuts a valley: the shaded incision first, then the water in it
      for (let pass = 0; pass < 2; pass++) {
        for (let i = 0; i < n - 1; i++) {
          const [ax, ay] = project(r.points[i][0], r.points[i][1]);
          const [bx, by] = project(r.points[i + 1][0], r.points[i + 1][1]);
          const grow = (i + 1) / (n - 1);
          ctx.beginPath();
          ctx.moveTo(ax, ay); ctx.lineTo(bx, by);
          ctx.lineCap = 'round';
          if (pass === 0) {                        // the cut bank, sun from NW
            ctx.lineWidth = Math.max(1.6, (0.00016 + 0.00030 * grow) * PROJ.s);
            ctx.strokeStyle = 'rgba(46,52,38,.30)';
          } else {
            ctx.lineWidth = Math.max(0.8, (0.00006 + 0.00016 * grow) * PROJ.s);
            ctx.strokeStyle = `rgba(96,158,190,${(0.55 + 0.35 * grow).toFixed(2)})`;
          }
          ctx.stroke();
        }
      }
      const m = r.points[n - 1], p0 = r.points[n - 2];
      const [mx, my] = project(m[0], m[1]);
      const dx = m[0] - p0[0], dy = m[1] - p0[1], L = Math.hypot(dx, dy) || 1;
      for (let k = 0; k < 5; k++) {                // the delta's distributaries
        const a = Math.atan2(-dy / L, dx / L) + (k - 2) * 0.26;
        const len = (0.0016 + rnd(k + m[0] * 1e4) * 0.0016) * PROJ.s;
        ctx.beginPath();
        ctx.moveTo(mx, my);
        ctx.lineTo(mx + Math.cos(a) * len, my - Math.sin(a) * len);
        ctx.lineWidth = Math.max(0.5, 0.00005 * PROJ.s);
        ctx.strokeStyle = 'rgba(120,168,196,.55)';
        ctx.stroke();
      }
    }
  }
}

// ------------------------------------------------------- the city fabric --
/* Tenochtitlan-Tlatelolco as urban fabric rather than blobs: a canal-and-
 * street network, blocks, house lots, courtyard compounds with cast shadows
 * and lime-plaster roofs, chinampa strips, gardens, and the precinct's own
 * stepped pyramids. AN ARTISTIC IMPRESSION rooted in Calnek's reconstruction
 * of the lot-and-canal fabric and the chroniclers' descriptions — every
 * position is a deterministic seed, not a record (About panel says so). */

const ISLAND_BBOX = {lon0: -99.1520, lon1: -99.1085, lat0: 19.4180, lat1: 19.4600};
const BLOCK = 0.00165;            // ~175 m block pitch, canal-to-canal
const LOT = BLOCK / 3;

function drawCityFabric() {
  const span = state.cam.span;
  if (span > 0.62) return;
  const phase = cityPhaseAt(state.t);
  const fp = CITY_BY_ID_FP();
  if (!fp) return;
  const lod = span < 0.10 ? 2 : span < 0.26 ? 1 : 0;
  const r = {width: cvs.width, height: cvs.height};
  const razeProg = phase === 'ruin' ? 1 : phase === 'siege'
    ? Math.max(0, Math.min(1, (state.t - D.meta.cityPhases.siege) / 0.20)) : 0;
  const charLat = 19.4165 + razeProg * 0.048;
  const traza = CITY_BY_ID['traza'];
  const pxPerDeg = PROJ.s;

  // 1 — the ground of the island itself: packed earth and lime, lifted a shade
  cpath(fp, true);
  ctx.fillStyle = 'rgba(186,174,148,.55)';
  ctx.fill();

  // 2 — chinampa strips: long narrow raised fields, the real thing's signature
  if (phase !== 'colonial') {
    for (const ch of D.geo.city.filter(f => f.kind === 'chinampa')) {
      const xs = ch.points.map(p => p[0]), ys = ch.points.map(p => p[1]);
      const lo0 = Math.min(...xs), lo1 = Math.max(...xs);
      const la0 = Math.min(...ys), la1 = Math.max(...ys);
      const strip = 0.000085;                       // ~9 m: chinampa width
      ctx.lineWidth = Math.max(0.6, strip * pxPerDeg * 0.75);
      for (let lo = lo0; lo < lo1; lo += strip * 2) {
        const [ax, ay] = project(lo, la0), [bx, by] = project(lo, la1);
        ctx.strokeStyle = 'rgba(104,138,78,.75)';
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
        const [cx2, cy2] = project(lo + strip, la0), [dx2, dy2] = project(lo + strip, la1);
        ctx.strokeStyle = 'rgba(84,126,158,.55)';   // the water between them
        ctx.beginPath(); ctx.moveTo(cx2, cy2); ctx.lineTo(dx2, dy2); ctx.stroke();
      }
      if (lod >= 1) {                                // willows on the margins
        ctx.fillStyle = 'rgba(58,92,48,.85)';
        for (let i = 0; i < 40; i++) {
          const lo = lo0 + rnd(i * 3 + lo0 * 1e4) * (lo1 - lo0);
          const la = la0 + rnd(i * 7 + la0 * 1e4) * (la1 - la0);
          const [tx, ty] = project(lo, la);
          ctx.beginPath(); ctx.arc(tx, ty, Math.max(0.8, 0.00003 * pxPerDeg), 0, 7); ctx.fill();
        }
      }
    }
  }

  // 3 — the canal-and-street network. Real fabric is not a chequerboard: the
  //     lines carry a seeded wander and varying width, and canals alternate
  //     with the streets that ran beside them.
  const canalW = Math.max(1.1, 0.00013 * pxPerDeg);
  const streetW = Math.max(0.8, 0.00009 * pxPerDeg);
  const jit = i => (rnd(i * 91.3) - 0.5) * BLOCK * 0.30;
  const wob = (i, k) => (rnd(i * 53.7 + k * 17.1) - 0.5) * BLOCK * 0.16;
  const line = (isCanal, pts, i) => {
    ctx.lineCap = 'round';
    ctx.strokeStyle = isCanal ? `rgba(84,131,166,${(0.55 + rnd(i) * 0.2).toFixed(2)})`
                              : `rgba(216,205,180,${(0.4 + rnd(i + 5) * 0.2).toFixed(2)})`;
    ctx.lineWidth = (isCanal ? canalW : streetW) * (0.7 + rnd(i + 9) * 0.7);
    ctx.beginPath();
    pts.forEach((p, k) => {
      const [x, y] = project(p[0], p[1]);
      k ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    });
    ctx.stroke();
  };
  // The grid belongs to the ISLAND. Without this clip the canals ruled on
  // across open water to the bbox corners — visible as a square lattice out
  // in the lake, and a plain falsehood about where the city was.
  ctx.save();
  cpath(fp, true);
  ctx.clip();
  let li = 0;
  for (let lat = ISLAND_BBOX.lat0; lat < ISLAND_BBOX.lat1; lat += BLOCK, li++) {
    const base = lat + jit(li);
    const pts = [];
    for (let lon = ISLAND_BBOX.lon0; lon <= ISLAND_BBOX.lon1 + 1e-9; lon += BLOCK)
      pts.push([lon, base + wob(li, lon * 1e4)]);
    line(li % 2 === 0, pts, li);
  }
  for (let lon = ISLAND_BBOX.lon0; lon < ISLAND_BBOX.lon1; lon += BLOCK, li++) {
    const base = lon + jit(li);
    const pts = [];
    for (let lat = ISLAND_BBOX.lat0; lat <= ISLAND_BBOX.lat1 + 1e-9; lat += BLOCK)
      pts.push([base + wob(li, lat * 1e4), lat]);
    line(li % 2 === 1, pts, li);
  }
  ctx.restore();

  // 3b — the causeways run THROUGH the city as its widest ground (NOT clipped:
  // a causeway's whole point is that it crosses the water)
  for (const f of D.geo.features) {
    if (f.kind !== 'causeway' && f.kind !== 'aqueduct') continue;
    cpath(f.points, false);
    ctx.lineCap = 'round';
    ctx.lineWidth = (f.kind === 'causeway' ? 0.00030 : 0.00010) * pxPerDeg;
    ctx.strokeStyle = f.kind === 'causeway' ? 'rgba(206,192,160,.95)'
                                            : 'rgba(150,190,214,.9)';
    ctx.stroke();
    if (f.kind === 'causeway') {                    // the parapet edge lines
      ctx.lineWidth = Math.max(0.5, 0.00003 * pxPerDeg);
      ctx.strokeStyle = 'rgba(120,104,74,.55)';
      ctx.stroke();
      // THE BREACHES: the defenders cut the causeways at their bridges and
      // the attackers spent the siege filling them in again — the single
      // tactical fact the whole siege turned on. Gaps close as it advances.
      if (phase === 'siege') {
        const prog = Math.max(0, Math.min(1,
          (state.t - D.meta.cityPhases.siege) / 0.20));
        const pts = f.points;
        for (let b = 0; b < 3; b++) {
          if (prog > (b + 1) / 3.4) continue;        // filled by now
          const u = 0.25 + b * 0.25;
          const seg = u * (pts.length - 1), si = Math.floor(seg), fu = seg - si;
          if (si + 1 >= pts.length) continue;
          const lo = pts[si][0] + (pts[si + 1][0] - pts[si][0]) * fu;
          const la = pts[si][1] + (pts[si + 1][1] - pts[si][1]) * fu;
          const [gx3, gy3] = project(lo, la);
          const gr = Math.max(1.5, 0.00012 * pxPerDeg);
          ctx.fillStyle = 'rgba(70,116,150,.95)';
          ctx.beginPath(); ctx.arc(gx3, gy3, gr, 0, 7); ctx.fill();
        }
      }
    }
  }

  // 3d — the water's edge: the canoe landings that made the island work. A
  //      lake city meets its lake at jetties, not at a clean line.
  if (lod >= 1) {
    const cxl = fp.reduce((a, q) => a + q[0], 0) / fp.length;
    const cyl = fp.reduce((a, q) => a + q[1], 0) / fp.length;
    for (let i = 0; i < fp.length; i++) {
      const a = fp[i], b = fp[(i + 1) % fp.length];
      for (let k = 0; k < 9; k++) {
        const u = (k + 0.5) / 9;
        const lo = a[0] + (b[0] - a[0]) * u, la = a[1] + (b[1] - a[1]) * u;
        const sd = Math.round(lo * 1e5) * 31 + Math.round(la * 1e5);
        if (rnd(sd) > 0.5) continue;
        const nx = lo - cxl, ny = la - cyl, L = Math.hypot(nx, ny) || 1;
        const reach = 0.00035 + rnd(sd + 1) * 0.00035;
        const [x1, y1] = project(lo, la);
        const [x2, y2] = project(lo + nx / L * reach, la + ny / L * reach);
        ctx.strokeStyle = 'rgba(154,132,98,.9)';
        ctx.lineWidth = Math.max(0.7, 0.00004 * pxPerDeg);
        ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
        if (state.t < 1521.414) {                    // canoes moored alongside
          ctx.strokeStyle = 'rgba(74,58,42,.85)';
          ctx.lineWidth = Math.max(0.6, 0.00003 * pxPerDeg);
          for (let m = 0; m < 3; m++) {
            const v = 0.35 + m * 0.22;
            const mx = x1 + (x2 - x1) * v, my = y1 + (y2 - y1) * v;
            const off = (m % 2 ? 1 : -1) * Math.max(1.2, 0.00006 * pxPerDeg);
            ctx.beginPath();
            ctx.moveTo(mx - (y2 - y1) / L * 0 + off, my);
            ctx.lineTo(mx + off, my + Math.max(1.6, 0.00007 * pxPerDeg));
            ctx.stroke();
          }
        }
      }
    }
  }

  // 3e — the fort of Xoloc where the southern causeway forks: the sources'
  //      two-towered work, and the meeting place of 8 November 1519
  if (lod >= 1 && phase !== 'colonial') {
    const [fx, fy] = project(-99.1350, 19.4060);
    const fw = Math.max(3, 0.00018 * pxPerDeg);
    ctx.fillStyle = 'rgba(20,15,11,.4)';
    ctx.fillRect(fx - fw / 2 + fw * 0.25, fy - fw / 2 + fw * 0.28, fw, fw * 0.8);
    ctx.fillStyle = 'rgb(218,206,176)';
    ctx.fillRect(fx - fw / 2, fy - fw / 2, fw, fw * 0.8);
    ctx.fillStyle = 'rgb(196,182,150)';
    ctx.fillRect(fx - fw / 2, fy - fw / 2, fw * 0.3, fw * 0.3);
    ctx.fillRect(fx + fw * 0.2, fy - fw / 2, fw * 0.3, fw * 0.3);
  }

  // 3c — canoes working the city canals: the traffic that fed a lake city,
  //      which stops when the brigantines take the water (1 Jun 1521)
  if (lod >= 1 && state.t < 1521.414) {
    const cl = Math.max(1.4, 0.00009 * pxPerDeg);
    ctx.strokeStyle = 'rgba(74,58,42,.85)';
    ctx.lineWidth = Math.max(0.7, cl * 0.5);
    for (let k = 0; k < 70; k++) {
      const along = rnd(k * 5.1);
      const which = Math.floor(rnd(k * 3.3) * 14);
      const horiz = k % 2 === 0;
      const fixed = ISLAND_BBOX.lat0 + which * BLOCK * (horiz ? 1 : 0)
                  + (horiz ? 0 : 0);
      let lat, lon;
      if (horiz) {
        lat = ISLAND_BBOX.lat0 + (which % 13) * BLOCK + jit((which % 13));
        lon = ISLAND_BBOX.lon0 + ((along + state.t * (12 + rnd(k) * 10)) % 1)
              * (ISLAND_BBOX.lon1 - ISLAND_BBOX.lon0);
      } else {
        lon = ISLAND_BBOX.lon0 + (which % 12) * BLOCK + jit((which % 12) + 13);
        lat = ISLAND_BBOX.lat0 + ((along + state.t * (12 + rnd(k) * 10)) % 1)
              * (ISLAND_BBOX.lat1 - ISLAND_BBOX.lat0);
      }
      if (!pointInPoly(lat, lon, fp)) continue;
      const [qx, qy] = project(lon, lat);
      ctx.beginPath();
      if (horiz) { ctx.moveTo(qx - cl, qy); ctx.lineTo(qx + cl, qy); }
      else { ctx.moveTo(qx, qy - cl); ctx.lineTo(qx, qy + cl); }
      ctx.stroke();
    }
  }

  // 4 — the lots: courtyard compounds, the Mexica house form (Calnek: several
  //     structures around a patio, on a lot reached from canal and street)
  // lime-plastered white through mud-brown, plus the darker earth roofs —
  // the tonal spread an aerial view actually shows
  const ROOFS = ['rgba(232,224,200,1)', 'rgba(220,206,176,1)', 'rgba(206,188,154,1)',
                 'rgba(186,162,126,1)', 'rgba(166,142,110,1)', 'rgba(150,126,98,1)'];
  const THATCH = ['rgba(176,150,106,1)', 'rgba(160,136,98,1)'];
  const hgt = Math.max(0.7, 0.000035 * pxPerDeg);   // one storey, in pixels
  let drawn = 0;
  for (let lat = ISLAND_BBOX.lat0; lat < ISLAND_BBOX.lat1; lat += LOT) {
    for (let lon = ISLAND_BBOX.lon0; lon < ISLAND_BBOX.lon1; lon += LOT) {
      const [px, py] = project(lon, lat);
      if (px < -30 || py < -30 || px > r.width + 30 || py > r.height + 30) continue;
      if (!pointInPoly(lat, lon, fp)) continue;
      const seed = Math.round(lat * 1e5) * 733 + Math.round(lon * 1e5);
      const dPre = Math.hypot(lat - 19.4346, lon + 99.1313);
      const inTraza = traza && pointInPoly(lat, lon, traza.points);
      if (phase === 'colonial' && !inTraza && rnd(seed) > 0.42) continue;
      // BLOCK CHARACTER: a whole block shares a character, so the fabric reads
      // as neighbourhoods rather than uniform grain — great lordly compounds
      // near the precinct, tight commoner wards toward the water, and gardens
      // in between (Calnek's lots vary by an order of magnitude in size).
      const bSeed = Math.floor(lat / BLOCK) * 977 + Math.floor(lon / BLOCK);
      const bChar = rnd(bSeed);
      const elite = bChar > 0.80 - Math.max(0, 0.30 - dPre * 12);
      const garden = !elite && bChar < 0.10;
      const density = phase === 'colonial' ? (inTraza ? 0.96 : 0.34)
        : garden ? 0.22 : elite ? 0.62 : Math.max(0.42, 1.02 - dPre * 18);
      if (rnd(seed) > density) continue;
      // skip the precinct footprints — they get their own architecture
      if (lat > 19.4326 && lat < 19.4366 && lon > -99.1334 && lon < -99.1292) continue;
      if (lat > 19.4494 && lat < 19.4520 && lon > -99.1386 && lon < -99.1340) continue;
      const charred = phase !== 'colonial' && razeProg > 0 && lat < charLat;
      const lotPx = LOT * pxPerDeg;
      const colonial = phase === 'colonial' && inTraza;
      // the compound: 2-4 wings around a patio, or a colonial block-house
      const wings = colonial ? 1 : elite ? 4 : 2 + Math.floor(rnd(seed + 5) * 3);
      const scale = elite ? 1.35 : garden ? 0.8 : 1;
      // A BLOCK SHARES ITS GRAIN: real fabric grows block by block, so the
      // compounds of one block share an orientation off the canal line and a
      // roofing material, and the next block is visibly a different quarter.
      const ang = (rnd(bSeed + 3) - 0.5) * 0.30;
      const blockRoof = rnd(bSeed + 11);
      ctx.save();
      ctx.translate(px, py - lotPx);
      if (Math.abs(ang) > 0.005) ctx.rotate(ang);
      for (let w = 0; w < wings; w++) {
        const s2 = seed + w * 37;
        const long = (colonial ? 0.80 : 0.34 + rnd(s2 + 1) * 0.22) * scale;
        const shortS = (colonial ? 0.80 : 0.20 + rnd(s2 + 2) * 0.14) * scale;
        const horiz = colonial ? false : (w % 2 === 0);
        const bw = (horiz ? long : shortS) * lotPx;
        const bh = (horiz ? shortS : long) * lotPx;
        const bx = (colonial ? 0.10 : (w === 0 ? 0.06 : w === 1 ? 0.55 : 0.20)) * lotPx;
        const by = (colonial ? 0.10 : (w === 2 ? 0.60 : w === 1 ? 0.10 : 0.08)) * lotPx;
        if (lod >= 1) {                              // cast shadow, sun from NW
          ctx.fillStyle = 'rgba(28,22,16,.36)';
          ctx.fillRect(bx + hgt * SUN.dx * 1.9, by + hgt * SUN.dy * 1.9, bw, bh);
        }
        // material by block, with per-house variation inside it
        const roof = charred ? `rgba(${34 + rnd(s2) * 14 | 0},${27 + rnd(s2) * 10 | 0},22,1)`
          : colonial ? (blockRoof > 0.45 ? 'rgba(198,132,104,1)' : 'rgba(214,168,138,1)')
          : blockRoof > 0.74 ? THATCH[Math.floor(rnd(s2 + 4) * 2)]
          : blockRoof > 0.50 ? ROOFS[Math.floor(rnd(s2 + 4) * 2) + 3]
                             : ROOFS[Math.floor(rnd(s2 + 4) * 3)];
        ctx.fillStyle = roof;
        if (colonial) {
          // the colonial block is a RING around a patio — the signature of
          // the centro's fabric, and of every traza house of the period
          ctx.fillRect(bx, by, bw, bh);
          ctx.fillStyle = 'rgba(150,132,104,.55)';
          ctx.fillRect(bx + bw * 0.26, by + bh * 0.26, bw * 0.48, bh * 0.48);
          if (lod >= 2 && rnd(s2 + 12) > 0.45) {     // a tree in the patio
            ctx.fillStyle = 'rgba(66,100,56,.9)';
            ctx.beginPath();
            ctx.arc(bx + bw * 0.5, by + bh * 0.5, Math.max(0.8, bw * 0.10), 0, 7);
            ctx.fill();
          }
          ctx.fillStyle = roof;
        } else {
          ctx.fillRect(bx, by, bw, bh);
          // some houses turn a corner: an L rather than a bar
          if (rnd(s2 + 21) > 0.62) {
            const sw = bw * (0.30 + rnd(s2 + 22) * 0.25);
            const sh = bh * (0.55 + rnd(s2 + 23) * 0.35);
            ctx.fillRect(bx + (rnd(s2 + 24) > 0.5 ? bw - sw : 0), by + bh, sw, sh * 0.5);
          }
        }
        if (lod >= 1) {                              // the lit and shaded faces
          ctx.fillStyle = charred ? 'rgba(20,16,12,.75)' : 'rgba(116,98,74,.46)';
          ctx.fillRect(bx, by + bh, bw, Math.max(0.5, hgt * 0.9));
          ctx.fillStyle = 'rgba(255,248,228,.24)';
          ctx.fillRect(bx, by - Math.max(0.4, hgt * 0.45), bw, Math.max(0.4, hgt * 0.45));
        }
        drawn++;
      }
      ctx.restore();
      // trees: a patio tree, and a stand of them where a block is a garden
      if (lod >= 2 && !colonial && (garden || rnd(seed + 9) > 0.55)) {
        ctx.fillStyle = garden ? 'rgba(56,92,46,.92)' : 'rgba(62,96,52,.9)';
        const nT = garden ? 4 : 1;
        for (let k = 0; k < nT; k++) {
          ctx.beginPath();
          ctx.arc(px + lotPx * (0.2 + rnd(seed + 20 + k) * 0.7),
                  py - lotPx * (0.2 + rnd(seed + 30 + k) * 0.7),
                  Math.max(0.9, lotPx * (garden ? 0.13 : 0.09)), 0, 7);
          ctx.fill();
        }
      }
    }
  }

  // 4b — the great market of Tlatelōlco, thick with people. The chroniclers'
  //      astonishment ("sixty thousand souls trading daily") is the one crowd
  //      the sources insist on; it thins to nothing once the siege closes.
  const mkt = CITY_BY_ID['tlatelolco-market'];
  if (mkt && lod >= 1 && phase !== 'colonial') {
    const xs = mkt.points.map(q => q[0]), ys = mkt.points.map(q => q[1]);
    const m0 = Math.min(...xs), m1 = Math.max(...xs);
    const n0 = Math.min(...ys), n1 = Math.max(...ys);
    const trade = state.t < D.meta.cityPhases.siege ? 1
      : Math.max(0, 1 - (state.t - D.meta.cityPhases.siege) / 0.10);
    const nP = Math.round(260 * trade);
    ctx.fillStyle = 'rgba(226,217,193,.85)';
    const [mx0, my0] = project(m0, n1), [mx1, my1] = project(m1, n0);
    ctx.fillRect(mx0, my0, mx1 - mx0, my1 - my0);
    for (let i = 0; i < nP; i++) {
      const lo = m0 + rnd(i * 2.3) * (m1 - m0);
      const la = n0 + rnd(i * 5.7) * (n1 - n0);
      const [qx, qy] = project(lo + Math.sin(state.t * 900 + i) * 0.000012,
                               la + Math.cos(state.t * 760 + i) * 0.000010);
      ctx.fillStyle = i % 5 ? 'rgba(66,52,40,.75)' : 'rgba(150,60,48,.7)';
      const pSz = Math.max(0.7, LOT * pxPerDeg * 0.055);
      ctx.fillRect(qx, qy, pSz, pSz);
    }
  }

  // 5 — the sacred precincts: walled, with their stepped pyramids
  if (phase !== 'colonial') {
    // the great court is ~400 m a side (the excavated precinct's own extent)
    drawPrecinct(-99.1313, 19.4346, 0.0040, 0.0036, charLat, razeProg, lod, true);
    drawPrecinct(-99.1372, 19.4507, 0.0022, 0.0020, charLat, razeProg, lod, false);
  } else {
    // the cathedral and the plaza mayor on the razed precinct
    const [zx, zy] = project(-99.1320, 19.4330);
    const zw = 0.0016 * pxPerDeg, zh = 0.0012 * pxPerDeg;
    ctx.fillStyle = 'rgba(196,186,166,.85)';
    ctx.fillRect(zx, zy - zh, zw, zh);
    const [cx3, cy3] = project(-99.1332, 19.4348);
    ctx.fillStyle = 'rgba(228,220,204,1)';
    ctx.fillRect(cx3, cy3 - 0.0006 * pxPerDeg, 0.0011 * pxPerDeg, 0.0006 * pxPerDeg);
  }
  return drawn;
}

function CITY_BY_ID_FP() {
  const f = D.geo.features.find(ff => ff.id === 'city-footprint');
  return f ? f.points : null;
}

/* A walled precinct with its great twin-shrined pyramid, drawn as concentric
 * terraces with a cast shadow — the shape the sources and the excavation
 * agree on, at visualization grade. */
function drawPrecinct(lon, lat, w, h, charLat, razeProg, lod, great) {
  const p = PROJ.s;
  const [x, y] = project(lon - w / 2, lat + h / 2);
  const W = w * p, H = h * p;
  const ruined = razeProg > 0 && lat < charLat;
  const stone = (k) => ruined ? `rgb(${74 - k * 8},${62 - k * 7},${50 - k * 6})`
                              : `rgb(${198 + k * 13},${184 + k * 13},${154 + k * 15})`;
  // the plaza floor, then the serpent wall around it
  ctx.fillStyle = ruined ? 'rgba(64,54,44,.9)' : 'rgba(226,217,193,.95)';
  ctx.fillRect(x, y, W, H);
  // the court is PAVED — the flagging is what makes it read as a floor rather
  // than a blank, and the sources are emphatic about the polished surface
  if (lod >= 1 && !ruined && W > 60) {
    ctx.strokeStyle = 'rgba(186,170,134,.35)';
    ctx.lineWidth = Math.max(0.3, W * 0.0035);
    const n = 9;
    ctx.beginPath();
    for (let i = 1; i < n; i++) {
      ctx.moveTo(x + W * i / n, y); ctx.lineTo(x + W * i / n, y + H);
      ctx.moveTo(x, y + H * i / n); ctx.lineTo(x + W, y + H * i / n);
    }
    ctx.stroke();
  }
  ctx.lineWidth = Math.max(1.4, W * 0.028);
  ctx.strokeStyle = ruined ? 'rgba(48,40,32,.95)' : 'rgba(150,130,92,.95)';
  ctx.strokeRect(x, y, W, H);
  // gates on the three causeway axes (the sources' three roads into the court)
  if (!ruined) {
    ctx.strokeStyle = 'rgba(226,217,193,1)';
    ctx.beginPath();
    ctx.moveTo(x, y + H * 0.46); ctx.lineTo(x, y + H * 0.60);
    ctx.moveTo(x + W * 0.44, y); ctx.lineTo(x + W * 0.58, y);
    ctx.moveTo(x + W * 0.44, y + H); ctx.lineTo(x + W * 0.58, y + H);
    ctx.stroke();
  }

  // THE GREAT TEMPLE — a stepped pyramid seen from above: concentric terraces
  // offset toward the sun, twin stairways on the west face, twin shrines atop.
  const bw = W * (great ? 0.34 : 0.36), bh = H * (great ? 0.36 : 0.40);
  const bx = x + W * (great ? 0.50 : 0.46), by = y + H * 0.30;
  ctx.fillStyle = 'rgba(20,15,11,.45)';
  ctx.fillRect(bx + bw * 0.17, by + bh * 0.19, bw, bh);
  const TER = 5;
  for (let s = 0; s < TER; s++) {
    const k = s / TER;
    ctx.fillStyle = stone(s);
    ctx.fillRect(bx + bw * k * 0.17, by + bh * k * 0.17,
                 bw * (1 - k * 0.34), bh * (1 - k * 0.34));
    ctx.strokeStyle = ruined ? 'rgba(30,24,18,.6)' : 'rgba(146,126,90,.55)';
    ctx.lineWidth = Math.max(0.4, W * 0.004);
    ctx.strokeRect(bx + bw * k * 0.17, by + bh * k * 0.17,
                   bw * (1 - k * 0.34), bh * (1 - k * 0.34));
  }
  if (!ruined) {                                     // the two great stairways
    ctx.fillStyle = 'rgba(178,160,122,1)';
    ctx.fillRect(bx - bw * 0.02, by + bh * 0.16, bw * 0.10, bh * 0.30);
    ctx.fillRect(bx - bw * 0.02, by + bh * 0.54, bw * 0.10, bh * 0.30);
    if (lod >= 1) {
      ctx.strokeStyle = 'rgba(120,104,76,.8)';
      ctx.lineWidth = Math.max(0.3, W * 0.003);
      for (let i = 0; i < 7; i++) {
        const yy = by + bh * (0.17 + i * 0.042);
        ctx.beginPath(); ctx.moveTo(bx - bw * 0.02, yy);
        ctx.lineTo(bx + bw * 0.08, yy); ctx.stroke();
        const y2 = by + bh * (0.55 + i * 0.042);
        ctx.beginPath(); ctx.moveTo(bx - bw * 0.02, y2);
        ctx.lineTo(bx + bw * 0.08, y2); ctx.stroke();
      }
    }
    ctx.fillStyle = 'rgba(70,110,150,1)';            // Tlaloc's shrine, north
    ctx.fillRect(bx + bw * 0.40, by + bh * 0.26, bw * 0.24, bh * 0.20);
    ctx.fillStyle = 'rgba(178,66,48,1)';             // Huitzilopochtli's, south
    ctx.fillRect(bx + bw * 0.40, by + bh * 0.54, bw * 0.24, bh * 0.20);
  }

  if (lod >= 1 && great) {
    // the round temple of Ehecatl-Quetzalcoatl, facing the great temple
    const [rx, ry] = project(lon - w * 0.16, lat);
    const rr = W * 0.062;
    ctx.fillStyle = 'rgba(20,15,11,.4)';
    ctx.beginPath(); ctx.arc(rx + rr * 0.35, ry + rr * 0.4, rr, 0, 7); ctx.fill();
    ctx.fillStyle = ruined ? 'rgb(66,56,46)' : 'rgb(212,200,170)';
    ctx.beginPath(); ctx.arc(rx, ry, rr, 0, 7); ctx.fill();
    ctx.fillStyle = ruined ? 'rgb(56,48,40)' : 'rgb(228,218,190)';
    ctx.beginPath(); ctx.arc(rx, ry, rr * 0.55, 0, 7); ctx.fill();
    // the ballcourt: the double-headed I of every Mesoamerican court
    const [gx, gy] = project(lon - w * 0.32, lat + h * 0.20);
    ctx.fillStyle = 'rgba(20,15,11,.35)';
    ctx.fillRect(gx + W * 0.012, gy + H * 0.014, W * 0.06, H * 0.22);
    ctx.fillStyle = ruined ? 'rgb(58,48,40)' : 'rgb(200,188,160)';
    ctx.fillRect(gx, gy, W * 0.06, H * 0.22);
    ctx.fillRect(gx - W * 0.032, gy, W * 0.124, H * 0.055);
    ctx.fillRect(gx - W * 0.032, gy + H * 0.165, W * 0.124, H * 0.055);
    // the tzompantli platform south of the great temple
    const [sx, sy] = project(lon - w * 0.06, lat - h * 0.26);
    ctx.fillStyle = ruined ? 'rgb(56,48,40)' : 'rgb(206,194,166)';
    ctx.fillRect(sx, sy, W * 0.13, H * 0.045);
    // the calmecac ranges along the north and west walls — the schools and
    // priests' houses that filled the court's edges
    for (let i = 0; i < 6; i++) {
      const rw = W * 0.115, rh = H * 0.06;
      const rx2 = x + W * (0.08 + i * 0.145), ry2 = y + H * 0.045;
      ctx.fillStyle = 'rgba(20,15,11,.28)';
      ctx.fillRect(rx2 + rw * 0.1, ry2 + rh * 0.35, rw, rh);
      ctx.fillStyle = ruined ? 'rgb(60,50,42)' : 'rgb(220,208,178)';
      ctx.fillRect(rx2, ry2, rw, rh);
      if (i < 4) {
        const cw2 = W * 0.06, ch2 = H * 0.105;
        const cx4 = x + W * 0.035, cy4 = y + H * (0.18 + i * 0.18);
        ctx.fillStyle = 'rgba(20,15,11,.28)';
        ctx.fillRect(cx4 + cw2 * 0.2, cy4 + ch2 * 0.2, cw2, ch2);
        ctx.fillStyle = ruined ? 'rgb(58,48,40)' : 'rgb(214,202,172)';
        ctx.fillRect(cx4, cy4, cw2, ch2);
      }
    }
    // smaller temples ringing the court
    for (let i = 0; i < 5; i++) {
      const a = 0.12 + i * 0.19;
      const [tx, ty] = project(lon - w * (0.36 - i * 0.02), lat + h * (0.34 - a * 1.4));
      const tw = W * 0.05, th = H * 0.055;
      ctx.fillStyle = 'rgba(20,15,11,.3)';
      ctx.fillRect(tx + tw * 0.3, ty + th * 0.3, tw, th);
      ctx.fillStyle = ruined ? 'rgb(62,52,42)' : 'rgb(216,204,174)';
      ctx.fillRect(tx, ty, tw, th);
    }
  }
}

function render() {
  while (svg.firstChild) svg.removeChild(svg.firstChild);
  computeProj();
  drawWorld();                                     // the raster world, first

  drawSubstrate();                                 // land, sea, sierra — always
  if (state.layers.water) drawWater();
  if (state.layers.city) drawCity();
  if (state.layers.tribute) drawTribute();
  if (state.layers.track) drawTrack();
  if (state.layers.works) drawWorksHit();
  if (state.layers.figures) drawFigures();
  if (state.layers.epidemic) drawEpidemic();
  if (state.layers.altepetl) drawAltepetl();
  if (state.layers.events) drawEvents();

  updateReadout();
  updateTimeline();
  updateChapters();
  updateLegend();
  updateForces();
  updateSiege();
  updatePeople();
  if (state.selection) openCard(state.selection);
}

// The ground (rounds 2-3): under everything, the vector land/sea fallback;
// over it, the REAL terrain — SRTM land + ETOPO shelf rendered by
// build/terrain.py per view and season, crossfaded by zoom and by the wet/dry
// year. The 1519 lakes are drawn over the modern terrain deliberately:
// reconstruction over measurement, each labelled as what it is.
const TERRAIN = [
  {id: 'meso'},
  {id: 'corridor'},
  {id: 'basin'},
  {id: 'city'},
];

/* The terrain levels stack — the coarse one stays opaque and the fine one
 * fades in over it — so mid-fade the screen shows 0.5*coarse + 0.5*fine. Both
 * rasters carry the same mountains, but their hillshades are only correlated
 * r=0.89 (meso/corridor) and r=0.95 (corridor/basin), so averaging them does
 * not blend, it DILUTES: high-pass detail energy dips about 10% at the 50/50
 * point of each transition. Small, but it is a visible softening exactly while
 * the camera is moving.
 *
 * MEASURED, and smaller than it first looked: an earlier pass put the dip at
 * 48% by comparing basin against MESO — wrong base layer. By the time basin
 * fades in, corridor is already fully opaque, and corridor carries 93.7% of
 * basin's detail. Measure against what is actually on screen underneath.
 *
 * Easing hard through the middle cannot fix the worst case (the 50/50 point is
 * crossed either way, and stays at ~90%) but it cuts how long the camera sits
 * near it — alpha is between 0.3 and 0.7 for 11% of the band instead of 40%.
 * Mean detail across the band: meso->corridor 92.9% -> 97.4%, corridor->basin
 * 92.5% -> 95.3%. The curve is gentle at both ends, which is what stops a pop.
 * Band widths are unchanged; only the shape was wrong. */
function _snap(t, k = 4) {
  if (t <= 0) return 0;
  if (t >= 1) return 1;
  const a = Math.pow(t, k), b = Math.pow(1 - t, k);
  return a / (a + b);
}

function terrainAlpha(id) {
  const span = state.cam.span;
  if (id === 'meso') return 1;
  if (id === 'corridor') return _snap(Math.max(0, Math.min(1, (7.5 - span) / 1.8)));
  if (id === 'basin') return _snap(Math.max(0, Math.min(1, (2.6 - span) / 0.7)));
  return _snap(Math.max(0, Math.min(1, (0.55 - span) / 0.18)));
}

/* The vector half of the substrate. The raster half (background, seas,
 * terrain) is drawn on the canvas by drawWorld() — they share project(). */
function drawSubstrate() {
  const g = el('g', {'data-layer': 'substrate'});
  const wet = wetness(state.t);
  if (state.cam.span > 8) {
    for (const s of D.geo.seaLabels || [])
      g.appendChild(el('text', Object.assign({class: 'sealab'},
        xyAttrs(s.lon, s.lat)), s.label));
  }
  for (const p of D.geo.peaks || []) {
    const wantMeso = state.cam.span > 2.5;
    if (p.views !== 'both' && p.views !== (wantMeso ? 'meso' : 'basin')) continue;
    const [x, y] = project(p.lon, p.lat);
    if (!onScreen(x, y)) continue;
    g.appendChild(el('path', {d: `M${x},${y - 5} L${x - 4.5},${y + 3} L${x + 4.5},${y + 3} Z`,
      fill: 'rgba(230,225,215,.7)', stroke: 'rgba(0,0,0,.45)', 'stroke-width': 0.7}));
    if (!wantMeso || p.views !== 'basin')
      g.appendChild(el('text', {x: x + 7, y: y + 3, class: 'peaklab'}, p.label));
  }
  svg.appendChild(g);
  updateAtmosphere(wet);
}

// Atmosphere lives in persistent HTML (not the rebuilt SVG) so its CSS
// animations survive every render: drifting cloud shadows scaled by the wet
// season, and Popocatépetl's plume for its attested 1519-1528 active years
// (see the 'Ordaz climbs the smoking mountain' event card).
function updateAtmosphere(wet) {
  const clouds = $('#clouds');
  clouds.style.opacity = (0.35 + 0.65 * wet).toFixed(2);
  clouds.classList.toggle('hidden', state.cam.span < 0.4);
  const plume = $('#plume');
  const active = state.t >= 1519.0 && state.t <= 1528.5 && state.cam.span < 6;
  plume.classList.toggle('hidden', !active);
  if (active) {
    const [x, y] = project(-98.628, 19.023);
    plume.style.left = (x - 9) + 'px';
    plume.style.top = (y - 30) + 'px';
    plume.style.transform = `scale(${Math.min(2.2, 1.6 / state.cam.span + 0.4)})`;
  }
  // the razing: smoke stands over the city while it is being unmade
  const smoke = $('#smoke');
  const razing = state.t >= 1521.53 && state.t <= 1521.645 && state.cam.span < 2.5;
  smoke.classList.toggle('hidden', !razing);
  if (razing) {
    const [x, y] = project(-99.132, 19.437);
    smoke.style.left = (x - 12) + 'px';
    smoke.style.top = (y - 34) + 'px';
    smoke.style.transform = `scale(${Math.min(3, 0.9 / state.cam.span + 0.5)})`;
  }
}

function xyAttrs(lon, lat) {
  const [x, y] = project(lon, lat);
  return {x, y};
}

// The modelled smallpox wave: a halo on each polity while its onset window is
// open. The layer label says "modelled"; the About panel carries the band.
function drawEpidemic() {
  const g = el('g', {'data-layer': 'epidemic'});
  // the wavefront: the modelled front's reach at t, expanding from the
  // documented coastal seed — an isochrone of the network wave, drawn as the
  // geographic circle it approximates
  const fr = D.meta.epidemicFront;
  if (fr && state.t > fr.t0 && state.t < 1521.9) {
    const rkm = fr.kmPerYear * (state.t - fr.t0);
    if (rkm < 1300) {
      const [cx, cy] = project(fr.lon, fr.lat);
      const rpx = (rkm / 110.6) * PROJ.s;
      const fade = Math.max(0.15, 1 - rkm / 1300);
      g.appendChild(el('circle', {cx, cy, r: rpx, fill: 'none',
        stroke: '#8e6fb8', 'stroke-width': 1.4, 'stroke-dasharray': '7 7',
        opacity: (0.5 * fade).toFixed(3)}));
      g.appendChild(el('circle', {cx, cy, r: Math.max(0, rpx - 9), fill: 'none',
        stroke: '#8e6fb8', 'stroke-width': 0.7, 'stroke-dasharray': '3 9',
        opacity: (0.3 * fade).toFixed(3)}));
    }
  }
  for (const e of ALTEPETL) {
    if (!e.epidemic) continue;
    const [t0, t1] = e.epidemic;
    if (state.t < t0 || state.t > t1 + 0.04) continue;
    const [x, y] = project(e.lon, e.lat);
    if (!onScreen(x, y)) continue;
    const a = state.t > t1 ? (1 - (state.t - t1) / 0.04) : 1;
    const rr = (GROUP_R[e.kind] || 4) + 4.5;
    g.appendChild(el('circle', {cx: x, cy: y, r: rr, fill: 'none',
      stroke: '#8e6fb8', 'stroke-width': 2.2, opacity: 0.55 * a}));
  }
  svg.appendChild(g);
}

// The 1519 lake system and the works — drawn always as the substrate; the
// geometry is a named reconstruction and its cards say so.
/* The lakes' fills are on the canvas (drawWorld); this keeps the island's
 * outline, which reads as an edge over the fabric rather than a wash. */
function drawWater() {
  const g = el('g', {'data-layer': 'water'});
  const fp = D.geo.features.find(f => f.id === 'city-footprint');
  if (fp && state.cam.span < 3.5) {
    g.appendChild(el('path', {d: pathOf(fp.points, true),
      fill: state.cam.span > 0.62 ? 'rgba(200,180,140,.22)' : 'none',
      stroke: 'rgba(206,188,150,.6)', 'stroke-width': 1}));
  }
  svg.appendChild(g);
}

// The phased city model (round 4): the same island, read across the timeline.
const CITY_CARD_OF = {
  'sacred-precinct': 'city-sacred-precinct',
  'palace-axayacatl': 'city-palace-axayacatl',
  'palace-moctezuma': 'city-palace-moctezuma',
  'tlatelolco-precinct': 'city-sacred-precinct',
  'tlatelolco-market': 'city-tlatelolco-market',
  'axis-north-south': 'city-campan', 'axis-east-west': 'city-campan',
  'canal-acequia-real': 'city-campan',
  'chinampas-south': 'city-chinampas', 'chinampas-west': 'city-chinampas',
  'chinampas-north': 'city-chinampas',
  'traza': 'city-traza', 'church-san-francisco': 'city-san-francisco',
  'church-first-cathedral': 'city-traza', 'colegio-tlatelolco-site': 'city-traza',
};

function cityPhaseAt(t) {
  const p = D.meta.cityPhases;
  if (t < p.siege) return 'mexica';
  if (t < p.fall) return 'siege';
  if (t < p.colonial) return 'ruin';
  return 'colonial';
}

const CITY_BY_ID = {};
(D.geo.city || []).forEach(f => { CITY_BY_ID[f.id] = f; });

const CITY_STYLE = {
  precinct: {fill: 'rgba(214,196,152,.45)', stroke: 'rgba(120,100,60,.8)', w: 1.2},
  palace:   {fill: 'rgba(196,178,140,.38)', stroke: 'rgba(110,95,60,.7)', w: 1},
  plaza:    {fill: 'rgba(222,210,180,.30)', stroke: 'rgba(120,105,70,.6)', w: 0.8},
  axis:     {stroke: 'rgba(205,190,160,.55)', w: 1.6},
  canal:    {stroke: 'rgba(96,150,196,.55)', w: 1.2},
  chinampa: {fill: 'rgba(110,150,90,.30)', stroke: 'rgba(110,150,90,.5)', w: 0.7},
  traza:    {fill: 'rgba(200,190,170,.16)', stroke: 'rgba(210,200,180,.7)', w: 1.1},
  church:   {},
};

function drawCity() {
  if (state.cam.span > 1.2) return;
  const phase = cityPhaseAt(state.t);
  const g = el('g', {'data-layer': 'city'});
  // once the canvas fabric is drawing the city for real, these polygons stop
  // painting and become click targets only — the fabric IS the picture
  const hitOnly = state.cam.span <= 0.62;
  for (const f of D.geo.city) {
    if (f.phases.indexOf(phase) < 0) continue;
    const st = hitOnly ? {} : (CITY_STYLE[f.kind] || {});
    if (hitOnly && f.closed) {
      const p = el('path', {d: pathOf(f.points, true), fill: 'rgba(0,0,0,0.001)',
                            stroke: 'none', class: 'work'});
      const card = BY_ID[CITY_CARD_OF[f.id]];
      if (card) p.addEventListener('click', ev => { ev.stopPropagation(); select(card); });
      g.appendChild(p);
      continue;
    }
    if (hitOnly) continue;
    if (f.kind === 'church') {
      const [x, y] = project(f.points[0][0], f.points[0][1]);
      g.appendChild(el('path', {d: `M${x},${y - 6} L${x},${y + 2} M${x - 3},${y - 3.5} L${x + 3},${y - 3.5}`,
        stroke: '#e8dfc8', 'stroke-width': 1.6, fill: 'none'}));
      continue;
    }
    if (f.kind === 'traza') {
      // the grid itself, not just the outline
      g.appendChild(el('path', {d: pathOf(f.points, true), fill: st.fill,
        stroke: st.stroke, 'stroke-width': st.w}));
      const [lon0, lat0] = f.points[0], [lon1, lat1] = f.points[2];
      for (let i = 1; i < 5; i++) {
        const lo = lon0 + (lon1 - lon0) * i / 5, la = lat0 + (lat1 - lat0) * i / 5;
        g.appendChild(el('path', {d: pathOf([[lo, lat0], [lo, lat1]], false),
          stroke: 'rgba(210,200,180,.35)', 'stroke-width': 0.7, fill: 'none'}));
        g.appendChild(el('path', {d: pathOf([[lon0, la], [lon1, la]], false),
          stroke: 'rgba(210,200,180,.35)', 'stroke-width': 0.7, fill: 'none'}));
      }
      continue;
    }
    const attrs = {d: pathOf(f.points, f.closed), 'stroke-width': st.w || 1};
    if (f.closed) { attrs.fill = st.fill || 'none'; attrs.stroke = st.stroke || 'none'; }
    else { attrs.fill = 'none'; attrs.stroke = st.stroke; }
    if (f.kind === 'canal' && f.confidence === 'contested')
      attrs['stroke-dasharray'] = '4 3';           // schematic alignments say so
    const p = el('path', attrs);
    const card = BY_ID[CITY_CARD_OF[f.id]];
    if (card) p.addEventListener('click', ev => { ev.stopPropagation(); select(card); });
    g.appendChild(p);
  }
  // The fabric itself is on the canvas (drawCityFabric). At fabric zoom the
  // razing wash is drawn there too; farther out it stands in for the city.
  // Rubble: the razing did not only burn the city, it PULLED IT DOWN into the
  // canals — the attackers' own method, and why the ruin reads as spoil.
  if ((phase === 'siege' || phase === 'ruin') && state.cam.span < 0.30) {
    const prog2 = phase === 'ruin' ? 1 :
      Math.max(0, Math.min(1, (state.t - D.meta.cityPhases.siege) / 0.20));
    const fp2 = D.geo.features.find(f => f.id === 'city-footprint').points;
    const rl = 19.4165 + prog2 * 0.048;
    for (let i = 0; i < 240; i++) {
      const lo = -99.1500 + rnd(i * 3.1) * 0.0400;
      const la = 19.4185 + rnd(i * 7.3) * 0.0395;
      if (la > rl || !pointInPoly(la, lo, fp2)) continue;
      const [rx, ry] = project(lo, la);
      if (!onScreen(rx, ry, 8)) continue;
      const rs = Math.max(1, 0.00006 * PROJ.s);
      g.appendChild(el('path', {
        d: `M${rx},${ry - rs} L${rx + rs},${ry} L${rx},${ry + rs} L${rx - rs},${ry} Z`,
        fill: i % 3 ? 'rgba(96,86,74,.72)' : 'rgba(54,46,38,.78)'}));
    }
  }
  if ((phase === 'siege' || phase === 'ruin') && state.cam.span > 0.62) {
    const fp = D.geo.features.find(f => f.id === 'city-footprint');
    const prog = phase === 'ruin' ? 1 :
      Math.max(0, Math.min(1, (state.t - D.meta.cityPhases.siege) / 0.20));
    g.appendChild(el('path', {d: pathOf(fp.points, true),
      fill: `rgba(20,14,10,${(0.45 * prog).toFixed(3)})`, stroke: 'none'}));
  }
  if (state.cam.span < 0.7 && (phase === 'mexica' || phase === 'siege')) {
    for (const c of D.geo.campanLabels || []) {
      const [x, y] = project(c.lon, c.lat);
      g.appendChild(el('text', {x, y, class: 'campanlab'}, c.name));
    }
  }
  svg.appendChild(g);
}

const WORK_STYLE = {
  causeway: {stroke: '#cbb894', w: 2.2, dash: null},
  aqueduct: {stroke: '#7fb8d8', w: 1.6, dash: '5 3'},
  dike: {stroke: '#9a8f7a', w: 1.8, dash: '2 3'},
};

function drawWorksHit() {
  if (state.cam.span > 3.5) return;                // sub-Basin detail
  const g = el('g', {'data-layer': 'works'});
  const sg = D.meta.siege;
  const inSiege = sg && state.t >= sg.start && state.t <= sg.end + 0.05;
  const cutAt = {};
  if (sg) sg.arteries.forEach(a => { cutAt[a.id] = a.cut; });
  for (const f of D.geo.features) {
    const st = WORK_STYLE[f.kind];
    if (!st) continue;
    let stroke = st.stroke, w = st.w;
    // during the siege the arteries show their state: crimson once cut
    if (inSiege && cutAt[f.id] !== undefined) {
      if (state.t >= cutAt[f.id]) { stroke = '#b0453a'; w = st.w + 0.6; }
      else { stroke = '#5f9e78'; }
    }
    const attrs = {d: pathOf(f.points, false), fill: 'none', stroke,
                   'stroke-width': w, 'stroke-linecap': 'round', class: 'work'};
    if (st.dash) attrs['stroke-dasharray'] = st.dash;
    const p = el('path', attrs);
    const card = BY_ID[f.id];
    if (card) p.addEventListener('click', ev => { ev.stopPropagation(); select(card); });
    g.appendChild(p);
  }
  // the brigantines hold the lake once the canoe fleet is broken
  const lakeCut = cutAt['lake'];
  if (inSiege && lakeCut !== undefined && state.t >= lakeCut && state.cam.span < 1.2) {
    for (const [blon, blat, rot] of [[-99.105, 19.445, 20], [-99.100, 19.415, -15],
                                     [-99.118, 19.400, 40]]) {
      const [x, y] = project(blon, blat);
      const bob = 1.5 * Math.sin(state.t * 3000 + x);
      g.appendChild(el('path', {
        d: `M${x},${y - 4 + bob} L${x - 3.5},${y + 3 + bob} L${x + 3.5},${y + 3 + bob} Z`,
        transform: `rotate(${rot} ${x} ${y})`,
        fill: '#e3ddcc', stroke: 'rgba(0,0,0,.55)', 'stroke-width': 0.8}));
    }
  }
  svg.appendChild(g);
}

// Tribute flows: arcs from every polity still inside the tribute system to
// Tenochtitlan. They thin out as the coalition grows — the map's argument in
// motion — and end with the system itself.
function drawTribute() {
  const [cx, cy] = project(TENOCH.lon, TENOCH.lat);
  const g = el('g', {'data-layer': 'tribute'});
  for (const e of ALTEPETL) {
    if (e.id === 'tenochtitlan') continue;
    const st = allegianceAt(e, state.t);
    if (st !== 'tributary') continue;
    const [x, y] = project(e.lon, e.lat);
    // arcs only from on-screen sources — at Basin/City scale the far provinces'
    // arcs would otherwise flood the view with lines that carry no local information
    if (!onScreen(x, y, 160)) continue;
    const mx = (x + cx) / 2 + (y - cy) * 0.12, my = (y + cy) / 2 - (x - cx) * 0.12;
    // dashes crawl toward the capital as time plays — tribute in motion,
    // deterministic in t so scrubbing stays reproducible
    g.appendChild(el('path', {d: `M${x},${y} Q${mx},${my} ${cx},${cy}`,
      fill: 'none', stroke: 'rgba(201,111,74,.34)', 'stroke-width': 0.9,
      'stroke-dasharray': '4 6',
      'stroke-dashoffset': String(-((state.t * 1200) % 10))}));
  }
  svg.appendChild(g);
}

// The campaign track: the Spanish-led column's dated itinerary, drawn as far
// as the timeline has reached.
function drawTrack() {
  const done = TRACK_EVENTS.filter(e => e.t <= state.t);
  if (done.length < 1) return;
  const g = el('g', {'data-layer': 'track'});
  let dPath = '';
  for (let i = 0; i < done.length; i++) {
    const [x, y] = project(done[i].lon, done[i].lat);
    dPath += (i ? ' L' : 'M') + x.toFixed(1) + ',' + y.toFixed(1);
  }
  g.appendChild(el('path', {d: dPath, fill: 'none', stroke: '#d9d2c2',
    'stroke-width': 1.6, 'stroke-dasharray': '6 4', opacity: 0.8,
    'stroke-dashoffset': String(-((state.t * 1500) % 10))}));
  // THE COLUMN, moving: between its dated waypoints the army is drawn in
  // transit — position interpolated in t, so playback shows the march itself
  const next = TRACK_EVENTS.find(e => e.t > state.t);
  const last = done[done.length - 1];
  let hx, hy, marching = false;
  if (next && state.t <= 1521.40) {
    const f = (state.t - last.t) / (next.t - last.t);
    const [x0, y0] = project(last.lon, last.lat);
    const [x1, y1] = project(next.lon, next.lat);
    hx = x0 + (x1 - x0) * f; hy = y0 + (y1 - y0) * f;
    marching = f > 0.02 && f < 0.98;
  } else {
    [hx, hy] = project(last.lon, last.lat);
  }
  if (state.t <= 1521.45) {
    const pulse = 1 + 0.18 * Math.sin(state.t * 2600);
    g.appendChild(el('circle', {cx: hx, cy: hy, r: 7 * pulse, fill: 'none',
      stroke: 'rgba(217,210,194,.55)', 'stroke-width': 1.2}));
    g.appendChild(el('circle', {cx: hx, cy: hy, r: 3.4, fill: '#efe9da',
      stroke: 'rgba(0,0,0,.65)', 'stroke-width': 1}));
    if (marching)
      g.appendChild(el('text', {x: hx + 10, y: hy + 3.5, class: 'mklab'},
        'the column, marching'));
  }
  svg.appendChild(g);
}

// ---- the figure-scale impression layer (round 5) --------------------------
// Files of soldiers, skirmish scenes, canoe traffic, porters, refugees,
// waterfowl. Every position is a pure function of (seed, t); contingent
// counts scale with forces.py's own bands; the About panel carries the
// impression disclaimer. Rooted, not attested — and the code says which.

function forcesBandsAt(t) {
  const rows = D.forces.filter(r => r[0] <= t);
  return rows.length ? rows[rows.length - 1][2] : null;
}

function trackPathAt(t) {
  const done = TRACK_EVENTS.filter(e => e.t <= t);
  if (!done.length) return null;
  const next = TRACK_EVENTS.find(e => e.t > t);
  const pts = done.map(e => project(e.lon, e.lat));
  let head = pts[pts.length - 1];
  if (next && t <= 1521.40) {
    const last = done[done.length - 1];
    const f = (t - last.t) / (next.t - last.t);
    const [x1, y1] = project(next.lon, next.lat);
    head = [head[0] + (x1 - head[0]) * f, head[1] + (y1 - head[1]) * f];
    pts.push(head);
  }
  return {pts, head};
}

function walkBack(pts, dist) {
  // point `dist` px behind the end of the polyline
  let i = pts.length - 1;
  while (i > 0 && dist > 0) {
    const [x0, y0] = pts[i - 1], [x1, y1] = pts[i];
    const seg = Math.hypot(x1 - x0, y1 - y0);
    if (seg >= dist) {
      const u = dist / seg;
      return [x1 + (x0 - x1) * u, y1 + (y0 - y1) * u];
    }
    dist -= seg; i--;
  }
  return pts[0];
}

const LAKESHORE_CANOE_TOWNS = ['xochimilco', 'texcoco', 'iztapalapa', 'culhuacan',
                               'azcapotzalco', 'tlacopan', 'mexicaltzingo',
                               'huitzilopochco', 'cuitlahuac', 'ecatepec'];

function drawFigures() {
  const g = el('g', {'data-layer': 'figures'});
  const t = state.t, span = state.cam.span;
  const bands = forcesBandsAt(t);

  // 1 — the column as a marching file: Spanish file at the head, the far
  //     larger allied contingent behind it, both scaled to the bands
  if (span < 7 && t >= 1519.12 && t <= 1521.40 && bands) {
    const tp = trackPathAt(t);
    if (tp) {
      const sp = bands['Spanish'] || [0, 0];
      const al = bands['Tlaxcalteca and Nahua allies'] || [0, 0];
      const nS = sp[1] ? Math.min(12, 4 + Math.round(Math.log10(sp[1]) * 2.4)) : 0;
      const nA = al[1] ? Math.min(24, Math.round(Math.log10(al[1]) * 4.4)) : 0;
      const gap = Math.max(3.5, 9 - span * 1.2);
      for (let i = 1; i <= nS; i++) {
        const [x, y] = walkBack(tp.pts, i * gap);
        g.appendChild(el('circle', {cx: x, cy: y, r: 1.6, fill: '#cfd4da',
          stroke: 'rgba(0,0,0,.5)', 'stroke-width': 0.4}));
      }
      for (let i = 1; i <= nA; i++) {
        const [x, y] = walkBack(tp.pts, (nS + i) * gap + 3);
        g.appendChild(el('circle', {cx: x, cy: y, r: 1.5,
          fill: i % 3 ? '#d0b98a' : '#b98f6a',
          stroke: 'rgba(0,0,0,.45)', 'stroke-width': 0.4}));
      }
    }
  }

  // 2 — skirmish scenes: defenders ring the ground, attackers close on it
  if (span < 3.2) {
    const win = 0.06;
    for (const ev of D.eventsFull) {
      if (!/battle|massacre/.test(ev.kind)) continue;
      const dt = t - ev.t;
      const dur = ev.precision === 'day' ? 0.03 : 0.06;
      if (dt < 0 || dt > dur) continue;
      const ph = dt / dur;
      const [x, y] = project(ev.lon, ev.lat);
      if (!onScreen(x, y, 60)) continue;
      for (let i = 0; i < 9; i++) {
        const a = i / 9 * Math.PI * 2 + rnd(i + ev.t) * 0.5;
        const rr = 8 + rnd(i * 3 + 1) * 4 + Math.sin(t * 4000 + i) * 1.5;
        g.appendChild(el('circle', {cx: x + Math.cos(a) * rr, cy: y + Math.sin(a) * rr,
          r: 1.5, fill: '#4a4038', stroke: 'rgba(0,0,0,.4)', 'stroke-width': 0.4}));
      }
      const conv = ev.kind === 'massacre' ? 1 - ph * 0.55 : 1 - ph * 0.75;
      for (let i = 0; i < 11; i++) {
        const a = (rnd(i * 17 + 2) - 0.5) * 1.9 + Math.PI;   // from the west-ish
        const rr = (34 * conv + rnd(i * 5) * 8) * (0.8 + 0.4 * rnd(i));
        g.appendChild(el('circle', {cx: x + Math.cos(a) * rr, cy: y + Math.sin(a) * rr,
          r: 1.6, fill: i % 4 ? '#d0b98a' : '#cfd4da',
          stroke: 'rgba(0,0,0,.4)', 'stroke-width': 0.4}));
      }
    }
  }

  // 3 — the canoe-borne city: traffic between the lakeshore towns and the
  //     island, ending the day the brigantines break the fleet (1 Jun 1521)
  if (span < 1.8 && t < 1521.414 && TENOCH) {
    const [cx, cy] = project(TENOCH.lon, TENOCH.lat);
    for (let i = 0; i < 14; i++) {
      const town = BY_ID[LAKESHORE_CANOE_TOWNS[i % LAKESHORE_CANOE_TOWNS.length]];
      if (!town) continue;
      const [tx, ty] = project(town.lon, town.lat);
      let u = (t * (1.4 + rnd(i) * 0.8) * 40 + rnd(i * 31)) % 2;
      if (u > 1) u = 2 - u;                        // out and back
      const px = tx + (cx - tx) * u, py = ty + (cy - ty) * u;
      const dx = (cx - tx), dy = (cy - ty), L = Math.hypot(dx, dy) || 1;
      g.appendChild(el('path', {d: `M${px - dx / L * 2.6},${py - dy / L * 2.6} ` +
        `L${px + dx / L * 2.6},${py + dy / L * 2.6}`,
        stroke: '#e8e2d2', 'stroke-width': 1.1, opacity: 0.75}));
    }
  }

  // 4 — tribute porters: single file on the arcs, only while the town still
  //     stands tributary (the flows die as the coalition grows)
  if (span > 1.0 && span < 9 && TENOCH) {
    const [cx, cy] = project(TENOCH.lon, TENOCH.lat);
    let drawn = 0;
    for (let i = 0; i < ALTEPETL.length && drawn < 12; i++) {
      const e = ALTEPETL[(i * 7 + 3) % ALTEPETL.length];
      if (allegianceAt(e, t) !== 'tributary' || e.id === 'tenochtitlan') continue;
      const [x, y] = project(e.lon, e.lat);
      if (!onScreen(x, y, 100)) continue;
      const mx = (x + cx) / 2 + (y - cy) * 0.12, my = (y + cy) / 2 - (x - cx) * 0.12;
      const u = (t * 30 + rnd(i * 11)) % 1;
      const bx = (1 - u) * (1 - u) * x + 2 * (1 - u) * u * mx + u * u * cx;
      const by = (1 - u) * (1 - u) * y + 2 * (1 - u) * u * my + u * u * cy;
      g.appendChild(el('circle', {cx: bx, cy: by, r: 1.3, fill: '#c96f4a',
        opacity: 0.8}));
      drawn++;
    }
  }

  // 5 — the exodus: after the fall the survivors leave by the causeways
  if (t >= 1521.6137 && t <= 1521.75 && span < 1.4) {
    const outPh = (t - 1521.6137) / 0.136;
    for (const cid of ['causeway-tepeyac', 'causeway-tlacopan', 'causeway-iztapalapa']) {
      const f = D.geo.features.find(ff => ff.id === cid);
      if (!f) continue;
      const pts = f.points.map(p => project(p[0], p[1]));
      for (let i = 0; i < 5; i++) {
        const u = Math.min(0.98, (outPh * 1.3 + rnd(i * 13 + cid.length) * 0.35) % 1);
        const seg = u * (pts.length - 1), si = Math.floor(seg), fu = seg - si;
        const px = pts[si][0] + (pts[si + 1][0] - pts[si][0]) * fu;
        const py = pts[si][1] + (pts[si + 1][1] - pts[si][1]) * fu;
        g.appendChild(el('circle', {cx: px, cy: py, r: 1.4, fill: '#9a948a',
          opacity: 0.8 - 0.4 * u}));
      }
    }
  }

  // 6 — the lake's waterfowl (the chroniclers' bird-thick water), indifferent
  //     to the war
  if (span < 2.4) {
    const lake = D.geo.features.find(f => f.id === 'lake-texcoco');
    if (lake) {
      for (let i = 0; i < 8; i++) {
        const u = (rnd(i * 3) + t * (0.5 + rnd(i) * 0.4)) % 1;
        const v = (rnd(i * 5 + 1) + t * 0.13) % 1;
        const lon = -99.170 + u * 0.27, lat = 19.34 + v * 0.20;
        if (!pointInPoly(lat, lon, lake.points)) continue;
        const [x, y] = project(lon, lat);
        g.appendChild(el('path', {d: `M${x - 2.4},${y} L${x},${y - 1.6} L${x + 2.4},${y}`,
          stroke: 'rgba(230,228,218,.6)', 'stroke-width': 0.9, fill: 'none'}));
      }
    }
  }

  svg.appendChild(g);
}

const GROUP_R = {'Triple Alliance seat': 6, 'Rival empire': 5.5,
                 'Independent polity': 5, 'Tributary altepetl': 4,
                 'Spanish foundation': 4.5};

function drawAltepetl() {
  const g = el('g', {'data-layer': 'altepetl'});
  const labelBudget = state.cam.span > 6 ? 5 : 4.4;
  // Once the fabric is drawing the island for real, the two city dots are
  // redundant and sit on top of the precinct they stand for — drop them.
  const fabricOn = state.layers.city && state.cam.span <= 0.62;
  for (const e of ALTEPETL) {
    if (!activeAt(e, state.t)) continue;
    if (fabricOn && (e.id === 'tenochtitlan' || e.id === 'tlatelolco')) continue;
    const st = allegianceAt(e, state.t);
    if (!st) continue;
    const [x, y] = project(e.lon, e.lat);
    if (!onScreen(x, y)) continue;
    const a = fadeIn(state.t, e.from, 0.05);
    const r = GROUP_R[e.kind] || 4;
    const color = D.meta.stateColor[st] || '#888';
    const mk = el('g', {class: 'mk', opacity: a});
    mk.appendChild(el('circle', {cx: x, cy: y, r,
      fill: color, stroke: 'rgba(0,0,0,.55)', 'stroke-width': 1}));
    if (e.confidence === 'contested')
      mk.appendChild(el('circle', {cx: x, cy: y, r: r + 2.5, fill: 'none',
        stroke: color, 'stroke-width': 0.8, 'stroke-dasharray': '2 2', opacity: 0.7}));
    if (r >= labelBudget)
      mk.appendChild(el('text', {x: x + r + 3, y: y + 3.5, class: 'mklab'},
        e.name.split(' (')[0]));
    mk.addEventListener('click', ev => { ev.stopPropagation(); select(e); });
    g.appendChild(mk);
  }
  svg.appendChild(g);
}

const KIND_GLYPH = {battle: '#d9a441', massacre: '#c0392b', siege: '#e0a458',
                    political: '#5aa9e6', campaign: '#d9d2c2', epidemic: '#8e6fb8',
                    aftermath: '#8a8f98', religious: '#4a9a8f'};

/* Kind-specific marks: a battle is not a treaty is not a plague. */
function glyphEl(kind, x, y, c) {
  const S = 'rgba(0,0,0,.6)';
  switch (kind) {
    case 'battle':
      return el('path', {d: `M${x},${y - 5.5} L${x + 1.6},${y - 1.6} L${x + 5.5},${y} ` +
        `L${x + 1.6},${y + 1.6} L${x},${y + 5.5} L${x - 1.6},${y + 1.6} L${x - 5.5},${y} ` +
        `L${x - 1.6},${y - 1.6} Z`, fill: c, stroke: S, 'stroke-width': 1});
    case 'massacre':
      return el('path', {d: `M${x - 4.5},${y - 3.6} L${x + 4.5},${y - 3.6} L${x},${y + 4.6} Z`,
        fill: c, stroke: S, 'stroke-width': 1});
    case 'epidemic':
      return el('path', {d: `M${x - 1.6},${y - 5} h3.2 v3.4 h3.4 v3.2 h-3.4 v3.4 h-3.2 ` +
        `v-3.4 h-3.4 v-3.2 h3.4 Z`, fill: c, stroke: S, 'stroke-width': 1});
    case 'political':
      return el('circle', {cx: x, cy: y, r: 4, fill: c, stroke: S, 'stroke-width': 1});
    case 'religious': {
      const gg = el('g', {});
      gg.appendChild(el('circle', {cx: x, cy: y, r: 4, fill: 'none', stroke: c,
        'stroke-width': 1.6}));
      gg.appendChild(el('circle', {cx: x, cy: y, r: 1.4, fill: c}));
      return gg;
    }
    case 'aftermath':
      return el('rect', {x: x - 3.4, y: y - 3.4, width: 6.8, height: 6.8,
        fill: c, stroke: S, 'stroke-width': 1});
    default:      // campaign, siege: the diamond
      return el('rect', {x: x - 3.6, y: y - 3.6, width: 7.2, height: 7.2,
        transform: `rotate(45 ${x} ${y})`, fill: c, stroke: S, 'stroke-width': 1});
  }
}

function drawEvents() {
  const win = inCampaign(state.t) ? 0.055 : 0.45;
  const g = el('g', {'data-layer': 'events'});
  const visible = [];
  for (const ev of D.eventsFull) {
    const dt = state.t - ev.t;
    if (dt < -win * 0.3 || dt > win) continue;
    const [x, y] = project(ev.lon, ev.lat);
    if (!onScreen(x, y)) continue;
    visible.push({ev, x, y, dt});
  }
  // violence leaves a mark: battles, massacres and sieges pulse expanding
  // rings for a few days after their date — a pure function of t, so
  // scrubbing replays them identically
  for (const v of visible) {
    if (!/battle|massacre|siege/.test(v.ev.kind)) continue;
    const dur = v.ev.precision === 'day' ? 0.028 : 0.06;
    if (v.dt < 0 || v.dt > dur) continue;
    const ph = v.dt / dur;
    const base = v.ev.kind === 'siege' ? '224,132,64' : '190,60,45';
    for (const off of [0, 0.33, 0.66]) {
      const p = (ph + off) % 1;
      g.appendChild(el('circle', {cx: v.x, cy: v.y, r: 6 + p * 26, fill: 'none',
        stroke: `rgba(${base},${(0.55 * (1 - p) * (1 - ph * 0.5)).toFixed(3)})`,
        'stroke-width': 2 - p}));
    }
  }
  // markers + collision-avoided labels: stack instead of overprint, and past
  // four stacked labels show the marker alone (the card still carries it)
  const boxes = [];
  visible.sort((a, b) => a.y - b.y || a.x - b.x);
  for (const v of visible) {
    const a = 1 - Math.max(0, v.dt) / win;
    const c = KIND_GLYPH[v.ev.kind] || '#ccc';
    const mk = el('g', {class: 'mk evmk', opacity: 0.3 + 0.7 * a});
    mk.appendChild(glyphEl(v.ev.kind, v.x, v.y, c));
    const wpx = v.ev.name.length * 5.3 + 10;
    let ly = v.y, placed = false;
    for (let slot = 0; slot < 4 && !placed; slot++) {
      const cand = v.y + slot * 13;
      if (!boxes.some(b => Math.abs(b.y - cand) < 12 &&
                           v.x + 8 < b.x + b.w && v.x + 8 + wpx > b.x)) {
        ly = cand; placed = true;
      }
    }
    if (placed) {
      boxes.push({x: v.x + 8, y: ly, w: wpx});
      if (ly !== v.y)
        mk.appendChild(el('path', {d: `M${v.x + 5},${v.y} L${v.x + 8},${ly - 3}`,
          stroke: 'rgba(200,195,180,.4)', 'stroke-width': 0.7, fill: 'none'}));
      mk.appendChild(el('text', {x: v.x + 9, y: ly + 3.5, class: 'mklab evlab'},
        v.ev.name));
    }
    mk.addEventListener('click', evn => { evn.stopPropagation(); select(v.ev); });
    g.appendChild(mk);
  }
  svg.appendChild(g);
}

function pathOf(points, close) {
  let d = '';
  for (let i = 0; i < points.length; i++) {
    const [x, y] = project(points[i][0], points[i][1]);
    d += (i ? ' L' : 'M') + x.toFixed(1) + ',' + y.toFixed(1);
  }
  return close ? d + ' Z' : d;
}

function el(tag, attrs, text) {
  const n = document.createElementNS(SVGNS, tag);
  for (const k in attrs) n.setAttribute(k, attrs[k]);
  if (text != null) n.textContent = text;
  return n;
}

// ------------------------------------------------------------------ cards --
function eraTextFor(o, t) {
  if (!o.eras || !o.eras.length) return o.text || '';
  const m = o.eras.find(e => t >= e.from && t < e.to);
  return m ? m.text : (t < o.eras[0].from ? o.eras[0] : o.eras[o.eras.length - 1]).text;
}

function eraSpanFor(o, t) {
  if (!o.eras || !o.eras.length) return '';
  const m = o.eras.find(e => t >= e.from && t < e.to) || o.eras[o.eras.length - 1];
  return `Describing ${fmtT(m.from)} – ${fmtT(m.to)}`;
}

function select(o) { state.selection = o; openCard(o); }

const CONF_LABEL = {good: 'well attested', moderate: 'moderately attested',
                    contested: 'CONTESTED'};

function openCard(o) {
  const isEvent = o.precision !== undefined;
  $('#infoTag').textContent = isEvent ? `event · ${o.kind}` : (o.kind || o.layer || '');
  $('#infoName').textContent = o.name;

  let rows = (o.facts || []).map(([k, v]) =>
    `<div class="row"><b>${esc(k)}</b><span>${esc(v)}</span></div>`);
  if (!isEvent && o.allegiance) {
    const st = allegianceAt(o, state.t);
    if (st) rows.push(`<div class="row"><b>Standing now</b><span>` +
      `<i class="dot" style="background:${D.meta.stateColor[st]}"></i>` +
      `${esc(D.meta.stateLabel[st] || st)}</span></div>`);
  }
  if (o.confidence) rows.push(`<div class="row"><b>Confidence</b>` +
    `<span class="conf-${o.confidence}">${CONF_LABEL[o.confidence] || o.confidence}</span></div>`);
  $('#infoRows').innerHTML = rows.join('');

  let body = '';
  if (o.image) {
    body += `<img class="cardimg" src="${esc(bust(o.image.src))}" alt="">` +
            `<div class="imgcap">${esc(o.image.caption)}</div>` +
            `<div class="imgcredit">${esc(o.image.credit)}</div>`;
  }
  body += esc(isEvent ? (o.text || '') : eraTextFor(o, state.t));
  if (o.note) body += `<div class="note">${esc(o.note)}</div>`;
  if (o.chapterEvents && o.chapterEvents.length) {
    body += `<div class="tier">Events in this chapter` +
            (o.nEvents > o.chapterEvents.length ? ` (first ${o.chapterEvents.length} of ${o.nEvents})` : '') +
            `</div>` + o.chapterEvents.map(ev =>
              `<div class="prow chev-ev" data-ev="${esc(ev.id)}">${esc(fmtT(ev.t))} — ${esc(ev.name)}</div>`).join('');
  }
  if (o.accounts && o.accounts.length) {
    body += `<div class="tier">What the sources say</div>` + o.accounts.map(a =>
      `<div class="account"><div class="acc-src">${esc(a.source)}</div>` +
      `<div class="acc-claim">${esc(a.claim)}</div>` +
      `<div class="acc-note">${esc(a.note)}</div></div>`).join('');
  }
  $('#infoDesc').innerHTML = body;
  $('#infoDesc').querySelectorAll('.chev-ev').forEach(d =>
    d.onclick = () => {
      const full = D.eventsFull.find(f => f.id === d.dataset.ev);
      if (full) { seek(full.t); select(full); }
    });
  $('#infoSpan').textContent = isEvent ? '' : (o.kind === 'Chapter' ? '' : eraSpanFor(o, state.t));
  // Sources, with the pinned passage shown against the source it belongs to
  // where this model can locate one (register B2-b). A source with no pin is
  // not a lapse: its date comes from the modern chronologies synthesising
  // several accounts, and there is no single passage to point at.
  $('#infoCite').innerHTML = (o.sources || []).length
    ? 'Sources: ' + o.sources.map(s => {
        const pin = o.pins && o.pins[s];
        return pin ? `${esc(s)} <span class="pin">${esc(pin)}</span>` : esc(s);
      }).join(' · ')
    : '';
  $('#info').classList.remove('hidden');
}

// Chapters are cards too (round 3): the period's story, its image, its events.
function chapterCard(era) {
  return {
    kind: 'Chapter', name: era.name,
    facts: [['Span', `${fmtT(era.from)} – ${fmtT(era.to)}`],
            ['Events inside', String(era.nEvents || 0)]],
    text: (era.title ? era.title + '. ' : '') + (era.text || ''),
    image: era.image, chapterEvents: era.chapterEvents, nEvents: era.nEvents,
    sources: ['Chapter framing: this model (see About for the full source table)'],
  };
}

// --------------------------------------------------------------- readout --
function updateReadout() {
  $('#tBig').textContent = fmtT(state.t);
  $('#tCal').textContent = inCampaign(state.t) ? 'Julian calendar · day scale' : '';
  const era = eraAt(state.t);
  $('#eraName').textContent = era ? era.name : '';
  // live allegiance tally — reads the same series as the map (one source of truth)
  const counts = {};
  for (const e of ALTEPETL) {
    const st = allegianceAt(e, state.t);
    if (st) counts[st] = (counts[st] || 0) + 1;
  }
  const top = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 3);
  $('#statsBlock').innerHTML = top.map(([st, n]) =>
    `<div class="statline"><b>${esc(D.meta.stateLabel[st] || st)}</b>${n}</div>`).join('');
}

function updateLegend() {
  const counts = {};
  for (const e of ALTEPETL) {
    const st = allegianceAt(e, state.t);
    if (st) counts[st] = (counts[st] || 0) + 1;
  }
  const order = Object.keys(D.meta.stateColor);
  $('#legendBody').innerHTML = order.filter(st => counts[st]).map(st =>
    `<div class="lg"><i class="dot" style="background:${D.meta.stateColor[st]}"></i>` +
    `<span>${esc(D.meta.stateLabel[st] || st)}</span><b>${counts[st]}</b></div>`).join('');
}

function updateForces() {
  const rows = D.forces.filter(r => r[0] <= state.t);
  const panel = $('#forcesPanel');
  if (!rows.length) { panel.classList.add('hidden'); return; }
  const [, label, bands] = rows[rows.length - 1];
  panel.classList.remove('hidden');
  const COL = {'Spanish': '#6b7fa8', 'Tlaxcalteca and Nahua allies': '#3f8f6b',
               'Mexica defenders': '#a83232'};
  $('#forcesBody').innerHTML = `<div class="fphase">${esc(label)}</div>` +
    Object.entries(bands).filter(([, b]) => b[1] > 0).map(([c, b]) =>
      `<div class="lg"><i class="dot" style="background:${COL[c]}"></i>` +
      `<span>${esc(c.replace(' and Nahua allies', ' + Nahua allies'))}</span>` +
      `<b>${b[0].toLocaleString()}–${b[1].toLocaleString()}</b></div>`).join('') +
    `<div class="fnote">ranges, not numbers — the sources are parties to the count</div>`;
}

function updateSiege() {
  const s = D.meta.siege;
  const panel = $('#siegePanel');
  if (!s || state.t < s.start - 0.02 || state.t > s.end + 0.06) {
    panel.classList.add('hidden'); return;
  }
  panel.classList.remove('hidden');
  const cut = s.arteries.filter(a => state.t >= a.cut).length;
  $('#siegeBody').innerHTML =
    `<div class="fphase">${cut} of ${s.arteries.length} arteries severed</div>` +
    s.arteries.map(a => {
      const isCut = state.t >= a.cut;
      return `<div class="lg"><i class="dot" style="background:${isCut ? '#a83232' : '#3f8f6b'}"></i>` +
        `<span>${esc(a.label)}</span><b>${isCut ? 'cut ' + fmtT(a.cut) : 'open'}</b></div>`;
    }).join('') +
    `<div class="fnote">derived from the dated events, not narrated — Research/modeling/siege.py</div>`;
}

const PEOPLE_ENTS = D.entities.filter(e => e.layer === 'people');

function updatePeople() {
  const rows = PEOPLE_ENTS.filter(p =>
    p.active && state.t >= p.active[0] - 0.02 && state.t <= p.active[1] + 0.08);
  const panel = $('#peoplePanel');
  if (!rows.length) { panel.classList.add('hidden'); return; }
  panel.classList.remove('hidden');
  $('#peopleBody').innerHTML = rows.map(p =>
    `<div class="prow" data-id="${p.id}">${esc(p.name.split(' (')[0])}</div>`).join('');
  $('#peopleBody').querySelectorAll('.prow').forEach(d =>
    d.onclick = () => select(BY_ID[d.dataset.id]));
}

// -------------------------------------------------------------- timeline --
function buildTimeline() {
  const band = $('#eraBand'), labs = $('#eraLabels'), dots = $('#eventDots'),
        ticks = $('#tickRow');
  band.innerHTML = labs.innerHTML = dots.innerHTML = ticks.innerHTML = '';
  D.eras.forEach((e, i) => {
    const d = document.createElement('div');
    d.style.left = xOf(e.from) * 100 + '%';
    d.style.width = (xOf(e.to) - xOf(e.from)) * 100 + '%';
    d.style.background = i % 2 ? 'rgba(224,164,88,.20)' : 'rgba(90,169,230,.18)';
    d.title = e.name;
    d.onclick = () => seek(e.from + 1e-4);
    band.appendChild(d);
    if (xOf(e.to) - xOf(e.from) > 0.055) {
      const s = document.createElement('span');
      s.style.left = (xOf(e.from) + xOf(e.to)) / 2 * 100 + '%';
      s.textContent = e.name;
      labs.appendChild(s);
    }
  });
  (D.events || []).forEach(ev => {
    const d = document.createElement('div');
    d.style.left = xOf(ev.t) * 100 + '%';
    d.title = `${fmtT(ev.t)} — ${ev.name}`;
    d.onclick = e => {
      e.stopPropagation(); seek(ev.t);
      const full = D.eventsFull.find(f => f.id === ev.id);
      if (full) select(full);
    };
    dots.appendChild(d);
  });
  // the non-linear scale, made visible: breakpoints + segment labels
  TS.forEach((s, i) => {
    if (i) {
      const b = document.createElement('div');
      b.className = 'tsbreak';
      b.style.left = xOf(s.from) * 100 + '%';
      ticks.appendChild(b);
    }
    const lab = document.createElement('span');
    lab.className = 'tslab';
    lab.style.left = (xOf(s.from) + xOf(s.to)) / 2 * 100 + '%';
    lab.textContent = i === 1 ? 'day scale — the war, 1519–1521' :
      `${Math.round(s.from)}–${Math.round(s.to)}`;
    ticks.appendChild(lab);
  });
}

function updateTimeline() {
  const f = xOf(state.t) * 100;
  $('#trackFill').style.width = f + '%';
  $('#thumb').style.left = f + '%';
  const win = stepOf(state.t) * 2;
  const near = (D.events || []).filter(e => Math.abs(e.t - state.t) <= win);
  $('#eventReadout').textContent = near.length ? near[0].name : '';
}

function buildChapters() {
  $('#chapterList').innerHTML = D.eras
    .map((e, i) => `<div data-i="${i}">${esc(e.name)}</div>`).join('');
  $('#chapterList').querySelectorAll('div').forEach(d =>
    d.onclick = () => {
      const era = D.eras[+d.dataset.i];
      seek(era.from + 1e-4);
      select(chapterCard(era));
    });
}

function updateChapters() {
  const era = eraAt(state.t);
  $('#chapterList').querySelectorAll('div').forEach((d, i) =>
    d.classList.toggle('on', D.eras[i] === era));
}

// -------------------------------------------------------------- playback --
let raf = null, last = 0;

function tick(ts) {
  if (!state.playing) return;
  if (last) state.t = Math.min(T1, state.t + SPEEDS[state.speed] * (ts - last) / 1000);
  last = ts;
  if (state.t >= T1) pause();
  render(); syncHash();
  raf = requestAnimationFrame(tick);
}

function play()  { state.playing = true; last = 0; $('#playIcon').textContent = '❚❚';
                   raf = requestAnimationFrame(tick); }
function pause() { state.playing = false; $('#playIcon').textContent = '▶';
                   if (raf) cancelAnimationFrame(raf); }

function seek(t) {
  state.t = Math.max(T0, Math.min(T1, t));
  render(); syncHash();
}

function jumpEvent(dir) {
  const es = (D.events || []).map(e => e.t).sort((a, b) => a - b);
  const next = dir > 0 ? es.find(t => t > state.t + 1e-6)
                       : [...es].reverse().find(t => t < state.t - 1e-6);
  if (next != null) seek(next);
}

// ---- camera flights, wheel zoom, drag pan (round 3) ----------------------
let camAnim = null;

function flyTo(target, ms) {
  const from = {...state.cam};
  const t0 = performance.now();
  if (camAnim) cancelAnimationFrame(camAnim);
  const ease = u => u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
  const step = now => {
    const u = Math.min(1, (now - t0) / ms);
    const e = ease(u);
    // interpolate span in log space so the flight feels uniform
    state.cam = {
      cx: from.cx + (target.cx - from.cx) * e,
      cy: from.cy + (target.cy - from.cy) * e,
      span: Math.exp(Math.log(from.span) + (Math.log(target.span) - Math.log(from.span)) * e),
    };
    render();
    if (u < 1) camAnim = requestAnimationFrame(step);
    else { camAnim = null; syncHash(); }
  };
  camAnim = requestAnimationFrame(step);
}

function setView(v) {
  state.view = v;
  $('#viewBtns').querySelectorAll('button').forEach(b =>
    b.classList.toggle('on', b.dataset.v === v));
  flyTo(camOf(D.meta.views[v]), 750);
}

function nearestPreset() {
  let best = null, bestScore = 1e9;
  for (const [id, v] of Object.entries(D.meta.views)) {
    const c = camOf(v);
    const score = Math.abs(Math.log(c.span / state.cam.span))
                + Math.hypot(c.cx - state.cam.cx, c.cy - state.cam.cy) / c.span;
    if (score < bestScore) { bestScore = score; best = id; }
  }
  return bestScore < 0.35 ? best : null;
}

function refreshViewButtons() {
  const near = nearestPreset();
  $('#viewBtns').querySelectorAll('button').forEach(b =>
    b.classList.toggle('on', b.dataset.v === near));
}

// ------------------------------------------------------------------ hash --
// Throttled: Safari raises SecurityError past ~100 replaceState calls per 30 s,
// which the playback loop would exceed in two seconds.
let _lastHash = 0;
function syncHash() {
  const now = performance.now();
  if (now - _lastHash < 300) return;
  _lastHash = now;
  const near = nearestPreset();
  const v = near || `${state.cam.cx.toFixed(3)},${state.cam.cy.toFixed(3)},${state.cam.span.toFixed(3)}`;
  history.replaceState(null, '', `#t=${state.t.toFixed(4)}&v=${v}`);
}
function readHash() {
  const m = /[#&]t=(-?\d+(?:\.\d+)?)/.exec(location.hash);
  if (m) state.t = Math.max(T0, Math.min(T1, parseFloat(m[1])));
  const v = /[#&]v=([\w.,-]+)/.exec(location.hash);
  if (v && D.meta.views[v[1]]) {
    state.view = v[1];
    state.cam = camOf(D.meta.views[v[1]]);
  } else if (v) {
    const parts = v[1].split(',').map(Number);
    if (parts.length === 3 && parts.every(isFinite))
      state.cam = {cx: parts[0], cy: parts[1], span: Math.max(0.05, Math.min(40, parts[2]))};
  }
  if (!state.cam) state.cam = camOf(D.meta.views[state.view]);
}

// ------------------------------------------------------------------ about --
function buildAbout() {
  const a = D.meta.about;
  $('#aboutBody').innerHTML =
    `<p><b>What this is.</b> ${esc(a.what)}</p>` +
    `<p><b>On the name.</b> ${esc(a.naming)}</p>` +
    `<h3>What this model does not know</h3>` +
    a.notKnow.map(x => `<p>· ${esc(x)}</p>`).join('') +
    `<h3>Sources</h3>` + a.sources.map(x => `<p>· ${esc(x)}</p>`).join('') +
    `<h3>Method</h3><p>Every layer is generated from cited research models with selftests ` +
    `(Research/modeling/); two read-only audits gate every build: the card audit (era tiling, ` +
    `contested claims must carry their accounts, anachronisms) and the archaeological witness ` +
    `audit (drawn geography vs the Templo Mayor anchor table and literature bands). ` +
    `Data version: <span id="dvStamp">${esc(String(D.meta.dataVersion || 'dev'))}</span>.</p>` +
    (D.meta.updates || []).map(u =>
      `<h3>Update ${esc(u.version)} — ${esc(u.date)}: ${esc(u.title)}</h3>` +
      `<p>${esc(u.summary)}</p>` + u.items.map(i => `<p>· ${esc(i)}</p>`).join('')).join('');
}

// ------------------------------------------------------------------ wire --
function buildToggles() {
  $('#layerToggles').innerHTML = LAYERS.map(l =>
    `<label class="tog"><span>${esc(l.label)}</span>` +
    `<input type="checkbox" data-id="${l.id}"${state.layers[l.id] ? ' checked' : ''}><i></i></label>`
  ).join('');
  $('#layerToggles').querySelectorAll('input').forEach(i =>
    i.onchange = () => { state.layers[i.dataset.id] = i.checked; render(); });
}

function buildViews() {
  $('#viewBtns').innerHTML = Object.entries(D.meta.views).map(([id, v]) =>
    `<button data-v="${id}"${id === state.view ? ' class="on"' : ''}>${esc(v.label)}</button>`
  ).join('');
  $('#viewBtns').querySelectorAll('button').forEach(b =>
    b.onclick = () => setView(b.dataset.v));
}

function wire() {
  $('#playBtn').onclick  = () => state.playing ? pause() : play();
  $('#stepBack').onclick = () => seek(state.t - stepOf(state.t));
  $('#stepFwd').onclick  = () => seek(state.t + stepOf(state.t));
  $('#prevEvt').onclick  = () => jumpEvent(-1);
  $('#nextEvt').onclick  = () => jumpEvent(1);
  $('#speed').oninput = e => {
    state.speed = +e.target.value;
    $('#speedVal').textContent = SPEEDS[state.speed] + ' yr/s';
  };
  $('#speed').oninput({target: $('#speed')});

  const track = $('#track');
  const at = e => tOf((e.clientX - track.getBoundingClientRect().left) / track.clientWidth);
  let dragging = false;
  track.onpointerdown = e => { dragging = true; track.setPointerCapture(e.pointerId);
                               pause(); seek(at(e)); };
  track.onpointermove = e => { if (dragging) seek(at(e)); };
  track.onpointerup   = () => { dragging = false; };

  $('#infoClose').onclick  = () => { state.selection = null; $('#info').classList.add('hidden'); };
  $('#aboutBtn').onclick   = () => $('#about').classList.remove('hidden');
  $('#aboutClose').onclick = () => $('#about').classList.add('hidden');
  $('#chaptersChev').onclick = () => {
    const l = $('#chapterList');
    l.style.display = l.style.display === 'none' ? '' : 'none';
  };

  // camera: wheel zoom about the cursor, drag pan; a drag suppresses the
  // click-to-dismiss so panning never closes the open card
  svg.addEventListener('wheel', e => {
    e.preventDefault();
    const [lonA, latA] = unproject(e.clientX, e.clientY);
    state.cam.span = Math.max(0.05, Math.min(40,
      state.cam.span * Math.exp(e.deltaY * 0.0016)));
    computeProj();
    const [lonB, latB] = unproject(e.clientX, e.clientY);
    state.cam.cx += lonA - lonB;
    state.cam.cy += latA - latB;
    render(); refreshViewButtons(); syncHash();
  }, {passive: false});

  let panStart = null, panned = false;
  svg.addEventListener('pointerdown', e => {
    e.preventDefault();                    // no drag-select while panning
    panStart = {x: e.clientX, y: e.clientY, cx: state.cam.cx, cy: state.cam.cy};
    panned = false;
  });
  svg.addEventListener('dragstart', e => e.preventDefault());
  svg.addEventListener('selectstart', e => e.preventDefault());
  svg.addEventListener('pointermove', e => {
    if (!panStart || e.buttons === 0) return;
    const dx = e.clientX - panStart.x, dy = e.clientY - panStart.y;
    if (!panned && Math.hypot(dx, dy) < 5) return;
    panned = true;
    svg.setPointerCapture(e.pointerId);
    state.cam.cx = panStart.cx - dx / (PROJ.kx * PROJ.s);
    state.cam.cy = panStart.cy + dy / PROJ.s;
    render(); refreshViewButtons();
  });
  svg.addEventListener('pointerup', () => { panStart = null; syncHash(); });
  svg.addEventListener('click', () => {
    if (panned) { panned = false; return; }
    state.selection = null; $('#info').classList.add('hidden');
  });

  addEventListener('keydown', e => {
    if (e.target.tagName === 'INPUT') return;
    if (e.code === 'Space') { e.preventDefault(); state.playing ? pause() : play(); }
    else if (e.key === 'ArrowLeft')  e.shiftKey ? jumpEvent(-1) : seek(state.t - stepOf(state.t));
    else if (e.key === 'ArrowRight') e.shiftKey ? jumpEvent(1)  : seek(state.t + stepOf(state.t));
    else if (e.key === 'Escape') { state.selection = null; $('#info').classList.add('hidden'); }
  });

  addEventListener('resize', render);
  addEventListener('hashchange', () => { readHash(); render(); });
}

const esc = s => String(s == null ? '' : s)
  .replace(/[&<>"]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));

// ------------------------------------------------------------------ boot --
readHash();
preloadTerrain();
buildTimeline();
buildChapters();
buildToggles();
buildViews();
buildAbout();
wire();
render();

// Console handle, so verification is scriptable:
//   APP.seek(1521.5); APP.state; APP.allegianceAt(APP.BY_ID.tlaxcala, 1521)
window.APP = {state, seek, play, pause, render, project, activeAt, lastLE,
              allegianceAt, xOf, tOf, fmtT, BY_ID, LAYERS, setView};
